/* ---------------------------------------------------------
   TIER / POWER SYSTEM (MMR-style)
--------------------------------------------------------- */
const TIERS = ['BG1', 'BG2', 'NB', 'N-', 'N', 'S-', 'S', 'P-', 'P', 'C']; // ต่ำ -> สูง
const TIER_BASE_POWER = Object.fromEntries(TIERS.map((t, i) => [t, (i + 1) * 100]));

// หามือ (cls) ที่ตรงกับค่าพลังรบ (power) ที่กำหนด — ใช้ตอนแอดมินแก้พลังรบเองแบบ manual แล้วให้มืออัปเดตตาม
function clsFromPower(power) {
  let result = TIERS[0];
  for (const t of TIERS) {
    if (power >= TIER_BASE_POWER[t]) result = t;
  }
  return result;
}

// ระดับความยากของ AI Auto-Match: กรองผู้เล่นที่จะพิจารณาจับคู่ตามช่วงมือ
const DIFFICULTY_RANGES = {
  light: [TIERS.indexOf('BG1'), TIERS.indexOf('NB')],           // เกมเบา: BG1–NB
  medium: [TIERS.indexOf('NB'), TIERS.length - 1],              // เกมกลาง: NB ขึ้นไป
  heavy: [TIERS.indexOf('N'), TIERS.length - 1],                // เกมหนัก: N ขึ้นไป
};
function filterByDifficulty(list, difficulty) {
  const range = DIFFICULTY_RANGES[difficulty];
  if (!range) return list; // 'all' หรือค่าอื่น = ไม่กรอง
  const [lo, hi] = range;
  return list.filter(p => { const idx = TIERS.indexOf(p.cls); return idx >= lo && idx <= hi; });
}

