/* ---------------------------------------------------------
   MATCHMAKING ENGINE
--------------------------------------------------------- */
// สร้างตาราง "เจอกันกี่ครั้งวันนี้" (ทั้งเป็นทีมเดียวกันและคนละทีม) จากผลแข่งวันนี้ (ตามเวลาไทย)
function buildTogetherCounts(matchRecords) {
  const today = dayKeyOf(Date.now());
  const counts = {};
  matchRecords.forEach(r => {
    if (dayKeyOf(r.timestamp) !== today) return;
    const all = [...(r.teamA || []), ...(r.teamB || [])];
    for (let i = 0; i < all.length; i++) for (let j = i + 1; j < all.length; j++) {
      const key = all[i] < all[j] ? `${all[i]}-${all[j]}` : `${all[j]}-${all[i]}`;
      counts[key] = (counts[key] || 0) + 1;
    }
  });
  return counts;
}
function togetherCount(counts, aId, bId) {
  const key = aId < bId ? `${aId}-${bId}` : `${bId}-${aId}`;
  return counts[key] || 0;
}

// กลุ่มมือ 3 ระดับ ใช้สำหรับกระจายความหลากหลายของคู่แข่ง/คู่หูในแต่ละวัน
// low: BG1, BG2, NB | medium: N-, N | heavy: S-, S, P-, P, C
function tierGroup(cls) {
  const idx = TIERS.indexOf(cls);
  if (idx <= 2) return 'low';
  if (idx <= 4) return 'medium';
  return 'heavy';
}

// สถิติวันนี้ต่อผู้เล่น: เล่นไปกี่เกม, กี่เกมที่ "ข้ามกลุ่ม" (low เจอ non-low หรือ non-low เจอ low)
function buildTodayGroupStats(matchRecords, players) {
  const today = dayKeyOf(Date.now());
  const stats = {};
  matchRecords.forEach(r => {
    if (dayKeyOf(r.timestamp) !== today) return;
    const all = [...(r.teamA || []), ...(r.teamB || [])];
    const groups = all.map(id => tierGroup(players.find(p => p.id === id)?.cls));
    all.forEach((id, i) => {
      if (!stats[id]) stats[id] = { totalGames: 0, crossGames: 0 };
      stats[id].totalGames += 1;
      const myGroup = groups[i];
      const hasOtherGroup = groups.some(g => (myGroup === 'low') ? g !== 'low' : g === 'low');
      if (hasOtherGroup) stats[id].crossGames += 1;
    });
  });
  return stats;
}

// นับว่า "ลูกปัท" เจอมือที่ต่ำกว่าตัวเองไปแล้วกี่เกมวันนี้ (ใช้จำกัดโควตาไม่เกิน 1 เกม/วัน)
function countLukpatLowerGamesToday(matchRecords, players) {
  const today = dayKeyOf(Date.now());
  const lukpat = players.find(p => p.name === 'ลูกปัท');
  if (!lukpat) return 0;
  const lukpatIdx = TIERS.indexOf(lukpat.cls);
  let count = 0;
  matchRecords.forEach(r => {
    if (dayKeyOf(r.timestamp) !== today) return;
    const all = [...(r.teamA || []), ...(r.teamB || [])];
    if (!all.includes(lukpat.id)) return;
    const hasLower = all.some(id => id !== lukpat.id && TIERS.indexOf(players.find(p => p.id === id)?.cls) < lukpatIdx);
    if (hasLower) count += 1;
  });
  return count;
}

// กติกาเฉพาะ "ลูกปัท": ปกติต้องเจอเฉพาะมือเท่ากันหรือสูงกว่าเท่านั้น
// ยกเว้นได้เจอมือต่ำกว่าได้อย่างมากที่สุด 1 เกมต่อวัน
function isValidForLukpat(quartet, todayLukpatLowerGames) {
  const lukpat = quartet.find(p => p.name === 'ลูกปัท');
  if (!lukpat) return true;
  const lukpatIdx = TIERS.indexOf(lukpat.cls);
  const lowerCount = quartet.filter(p => p.id !== lukpat.id && TIERS.indexOf(p.cls) < lukpatIdx).length;
  if (lowerCount > 1) return false;
  if (lowerCount === 1 && todayLukpatLowerGames >= 1) return false;
  return true;
}

// นับว่าผู้เล่นแต่ละคน "เพิ่งเล่นติดต่อกันมากี่เกมแล้วโดยไม่มีเกมพัก" — นับย้อนจากเกมล่าสุดของวันนี้ (ทุกคอร์ทรวมกัน)
// พอเจอเกมไหนที่ผู้เล่นคนนี้ไม่ได้ลงเลย ถือว่าได้พักแล้ว หยุดนับ
function computeConsecutiveGames(matchRecords, playerId) {
  const today = dayKeyOf(Date.now());
  const todays = matchRecords.filter(r => dayKeyOf(r.timestamp) === today).sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));
  let count = 0;
  for (let i = todays.length - 1; i >= 0; i--) {
    if (todays[i].playerIds.includes(playerId)) count++;
    else break;
  }
  return count;
}

// ห้ามให้ใครเล่นติดต่อกันเกิน 2 เกม (เล่นได้ 2 ติดกัน แต่ห้ามเป็นเกมที่ 3 ติดกัน) — ถ้าคนไหนติด 2 อยู่แล้ว ตัดออกจากตัวเลือกถัดไปเลย
function violatesConsecutiveLimit(quartet, consecutiveCounts) {
  return quartet.some(p => (consecutiveCounts[p.id] || 0) >= 2);
}

function combinations(arr, size) {
  const result = [];
  const combo = [];
  function go(start) {
    if (combo.length === size) { result.push([...combo]); return; }
    for (let i = start; i < arr.length; i++) { combo.push(arr[i]); go(i + 1); combo.pop(); }
  }
  go(0);
  return result;
}

function permutations(arr) {
  if (arr.length <= 1) return [arr];
  const result = [];
  for (let i = 0; i < arr.length; i++) {
    const rest = [...arr.slice(0, i), ...arr.slice(i + 1)];
    for (const p of permutations(rest)) result.push([arr[i], ...p]);
  }
  return result;
}

// ให้โบนัส/โทษตามเป้าหมายความหลากหลายของมือแต่ละคน:
// มือต่ำ (low): อยากได้เกมกับกลุ่มอื่น (medium/heavy) ประมาณ 1 ใน ~4 เกม หลังจากเล่นมือเดียวกัน/ใกล้กันไปแล้ว 2 เกม
// มือ N- ขึ้นไป (medium/heavy): ส่วนใหญ่เจอมือเท่ากันหรือสูงกว่า แต่ต้องมีเจอ low อย่างน้อย 1 เกม/วัน
function tierMixBonus(quartet, todayGroupStats) {
  const groups = quartet.map(p => tierGroup(p.cls));
  const hasLow = groups.includes('low');
  const hasNonLow = groups.some(g => g !== 'low');
  let bonus = 0;
  quartet.forEach((p, i) => {
    const stat = todayGroupStats[p.id] || { totalGames: 0, crossGames: 0 };
    const myGroup = groups[i];
    if (myGroup === 'low') {
      const alreadyDiverse = stat.crossGames >= 1;
      const dueForDiversity = !alreadyDiverse && stat.totalGames >= 2;
      if (hasNonLow) {
        if (dueForDiversity) bonus += 60;
        else if (alreadyDiverse) bonus -= 50;
        else bonus -= 10;
      } else {
        if (dueForDiversity) bonus -= 20;
        else bonus += 15;
      }
    } else {
      const alreadyHasLow = stat.crossGames >= 1;
      if (hasLow) {
        bonus += alreadyHasLow ? -10 : 60;
      } else {
        bonus += (!alreadyHasLow && stat.totalGames >= 2) ? -20 : 10;
      }
    }
  });
  return bonus;
}

// คะแนนยิ่งต่ำยิ่งดี: บาลานซ์พลัง + เลี่ยงคนที่เจอกันซ้ำวันนี้ (น้ำหนักสูงสุด) + โบนัสตามเป้าหมายความหลากหลายมือ
// + เอนเอียงไปทางคนที่วันนี้เล่นน้อยกว่า (fairness) เพื่อพยายามให้ทุกคนได้เล่นใกล้เคียงกันในแต่ละวัน
function scoreQuartet(quartet, togetherCounts, todayGroupStats = {}) {
  const powers = quartet.map(p => p.power);
  const spread = Math.max(...powers) - Math.min(...powers);
  let repeatScore = 0;
  for (let i = 0; i < 4; i++) for (let j = i + 1; j < 4; j++) repeatScore += togetherCount(togetherCounts, quartet[i].id, quartet[j].id);
  const fairnessPenalty = quartet.reduce((s, p) => s + ((todayGroupStats[p.id]?.totalGames) || 0), 0) * 15;
  return spread + repeatScore * 250 + fairnessPenalty - tierMixBonus(quartet, todayGroupStats);
}

function pickBalancedQuartet(waiting, togetherCounts = {}, todayGroupStats = {}, todayLukpatLowerGames = 0, consecutiveCounts = {}) {
  if (waiting.length < 4) return null;
  let best = null, bestScore = Infinity;
  let fallback = null, fallbackScore = Infinity;
  for (const q of combinations(waiting, 4)) {
    const s = scoreQuartet(q, togetherCounts, todayGroupStats);
    if (s < fallbackScore) { fallbackScore = s; fallback = q; }
    if (!isValidForLukpat(q, todayLukpatLowerGames)) continue;
    if (violatesConsecutiveLimit(q, consecutiveCounts)) continue;
    if (s < bestScore) { bestScore = s; best = q; }
  }
  return best || fallback;
}

// คู่ผสม: ต้องได้ชาย 2 + หญิง 2 — ให้คะแนนแบบเดียวกัน (บาลานซ์ + เลี่ยงเจอซ้ำ + เป้าหมายความหลากหลายมือ + fairness)
function pickBalancedMixedQuartet(waiting, togetherCounts = {}, todayGroupStats = {}, todayLukpatLowerGames = 0, consecutiveCounts = {}) {
  const men = waiting.filter(p => p.gender === 'M');
  const women = waiting.filter(p => p.gender === 'F');
  if (men.length < 2 || women.length < 2) return null;
  let best = null, bestScore = Infinity;
  let fallback = null, fallbackScore = Infinity;
  for (const mPair of combinations(men, 2)) {
    for (const wPair of combinations(women, 2)) {
      const q = [...mPair, ...wPair];
      const s = scoreQuartet(q, togetherCounts, todayGroupStats);
      if (s < fallbackScore) { fallbackScore = s; fallback = q; }
      if (!isValidForLukpat(q, todayLukpatLowerGames)) continue;
      if (violatesConsecutiveLimit(q, consecutiveCounts)) continue;
      if (s < bestScore) { bestScore = s; best = q; }
    }
  }
  return best || fallback;
}

// เกมผสม: บังคับให้ได้มือต่ำ (BG1, BG2, NB) 2 คน + มือสูง (N ขึ้นไป) 2 คน มาลงคอร์ทเดียวกัน
function pickCrossTierQuartet(waiting, togetherCounts = {}, todayGroupStats = {}, todayLukpatLowerGames = 0, consecutiveCounts = {}) {
  const lowMaxIdx = TIERS.indexOf('NB');
  const highMinIdx = TIERS.indexOf('N');
  const lowPool = waiting.filter(p => TIERS.indexOf(p.cls) <= lowMaxIdx);
  const highPool = waiting.filter(p => TIERS.indexOf(p.cls) >= highMinIdx);
  if (lowPool.length < 2 || highPool.length < 2) return null;
  let best = null, bestScore = Infinity;
  let fallback = null, fallbackScore = Infinity;
  for (const lowPair of combinations(lowPool, 2)) {
    for (const highPair of combinations(highPool, 2)) {
      const q = [...lowPair, ...highPair];
      const s = scoreQuartet(q, togetherCounts, todayGroupStats);
      if (s < fallbackScore) { fallbackScore = s; fallback = q; }
      if (!isValidForLukpat(q, todayLukpatLowerGames)) continue;
      if (violatesConsecutiveLimit(q, consecutiveCounts)) continue;
      if (s < bestScore) { bestScore = s; best = q; }
    }
  }
  return best || fallback;
}

// matchType: 'open' | 'men' | 'women' | 'mixed' | difficulty: 'all' | 'light' | 'medium' | 'heavy' | 'cross' (เกมผสม)
function pickQuartetByType(waiting, matchType, difficulty = 'all', togetherCounts = {}, todayGroupStats = {}, todayLukpatLowerGames = 0, consecutiveCounts = {}) {
  if (difficulty === 'cross') {
    let pool = waiting;
    if (matchType === 'men') pool = pool.filter(p => p.gender === 'M');
    if (matchType === 'women') pool = pool.filter(p => p.gender === 'F');
    return pickCrossTierQuartet(pool, togetherCounts, todayGroupStats, todayLukpatLowerGames, consecutiveCounts);
  }
  const pool = filterByDifficulty(waiting, difficulty);
  if (matchType === 'men') return pickBalancedQuartet(pool.filter(p => p.gender === 'M'), togetherCounts, todayGroupStats, todayLukpatLowerGames, consecutiveCounts);
  if (matchType === 'women') return pickBalancedQuartet(pool.filter(p => p.gender === 'F'), togetherCounts, todayGroupStats, todayLukpatLowerGames, consecutiveCounts);
  if (matchType === 'mixed') return pickBalancedMixedQuartet(pool, togetherCounts, todayGroupStats, todayLukpatLowerGames, consecutiveCounts);
  return pickBalancedQuartet(pool, togetherCounts, todayGroupStats, todayLukpatLowerGames, consecutiveCounts);
}

// Splits a quartet into red/blue teams: balances power (with synergy history as a bonus),
// hard-avoids putting a blocked pair on the same team (they can still share the court),
// and prefers a split that hasn't teamed the same two players together yet today.
// For 'mixed' matches, only considers splits where each team has exactly 1 man + 1 woman.
function chooseTeamSplit(quartet, pairStats, matchType = 'open', togetherCounts = {}) {
  const mateBonus = (aId, bId) => {
    const data = pairStats[aId]?.mates?.[bId];
    if (!data || data.games === 0) return 0;
    return (data.wins / data.games - 0.5) * 150;
  };
  const isBlockedTeammate = (a, b) => a.blocked.includes(b.id) || b.blocked.includes(a.id);
  const isMixedPair = (a, b) => a.gender !== b.gender;
  const splits = [[[0, 1], [2, 3]], [[0, 2], [1, 3]], [[0, 3], [1, 2]]];
  let best = null, bestDiff = Infinity;
  let fallback = null, fallbackDiff = Infinity;
  for (const [ta, tb] of splits) {
    const [a, b] = ta.map(i => quartet[i]);
    const [c, d] = tb.map(i => quartet[i]);
    if (matchType === 'mixed' && (!isMixedPair(a, b) || !isMixedPair(c, d))) continue;
    const effA = a.power + b.power + mateBonus(a.id, b.id);
    const effB = c.power + d.power + mateBonus(c.id, d.id);
    const repeatPenalty = (togetherCount(togetherCounts, a.id, b.id) + togetherCount(togetherCounts, c.id, d.id)) * 300;
    const diff = Math.abs(effA - effB) + repeatPenalty;
    if (diff < fallbackDiff) { fallbackDiff = diff; fallback = [a, b, c, d]; }
    if (isBlockedTeammate(a, b) || isBlockedTeammate(c, d)) continue;
    if (diff < bestDiff) { bestDiff = diff; best = [a, b, c, d]; }
  }
  return best || fallback;
}

function quartetToSlots(quartet, pairStats = {}, matchType = 'open', togetherCounts = {}) {
  return chooseTeamSplit(quartet, pairStats, matchType, togetherCounts);
}

// เติมเฉพาะช่องที่ยังว่างในคอร์ท โดยคงผู้เล่นที่วางไว้เอง (manual) ไว้ตามเดิม
// เลือกคนจากคิวรอมาเติมช่องที่เหลือ พยายามบาลานซ์พลัง 2 ทีม + เลี่ยงคู่ซ้ำ + เคารพบล็อก/ลูกปัท/เกมติดต่อกัน
function fillRemainingSlots(court, waiting, matchType, difficulty, togetherCounts, todayGroupStats, todayLukpatLowerGames, consecutiveCounts, pairStats) {
  const filled = court.players.map((p, i) => ({ i, p })).filter(x => x.p);
  const emptyIdx = court.players.map((p, i) => (p ? null : i)).filter(i => i !== null);
  if (emptyIdx.length === 0 || emptyIdx.length === 4) return null; // ไม่มีอะไรให้เติม หรือว่างหมด (ใช้เส้นทางปกติ)

  let pool = filterByDifficulty(waiting, difficulty);
  if (matchType === 'men') pool = pool.filter(p => p.gender === 'M');
  if (matchType === 'women') pool = pool.filter(p => p.gender === 'F');
  if (pool.length < emptyIdx.length) return null;

  const fixedPlayers = filled.map(f => f.p);
  const mateBonus = (a, b) => {
    const d = pairStats[a.id]?.mates?.[b.id];
    return d && d.games ? (d.wins / d.games - 0.5) * 150 : 0;
  };
  const isBlockedTeammate = (a, b) => a.blocked.includes(b.id) || b.blocked.includes(a.id);

  let best = null, bestScore = Infinity;
  for (const combo of combinations(pool, emptyIdx.length)) {
    const fullQuartet = [...fixedPlayers, ...combo];
    if (!isValidForLukpat(fullQuartet, todayLukpatLowerGames)) continue;
    if (violatesConsecutiveLimit(fullQuartet, consecutiveCounts)) continue;

    for (const perm of permutations(combo)) {
      const players4 = [null, null, null, null];
      filled.forEach(f => { players4[f.i] = f.p; });
      emptyIdx.forEach((slotIdx, k) => { players4[slotIdx] = perm[k]; });

      const teamA = [players4[0], players4[1]];
      const teamB = [players4[2], players4[3]];
      if (isBlockedTeammate(teamA[0], teamA[1]) || isBlockedTeammate(teamB[0], teamB[1])) continue;

      const effA = teamA[0].power + teamA[1].power + mateBonus(teamA[0], teamA[1]);
      const effB = teamB[0].power + teamB[1].power + mateBonus(teamB[0], teamB[1]);
      let repeatScore = 0;
      for (let i = 0; i < 4; i++) for (let j = i + 1; j < 4; j++) repeatScore += togetherCount(togetherCounts, players4[i].id, players4[j].id);
      const fairness = combo.reduce((s, p) => s + ((todayGroupStats[p.id]?.totalGames) || 0), 0) * 15;
      const score = Math.abs(effA - effB) + repeatScore * 250 + fairness - tierMixBonus(players4, todayGroupStats);

      if (score < bestScore) { bestScore = score; best = players4; }
    }
  }
  return best;
}

const TIER_POINT_THRESHOLD = 10; // สะสมแต้มขึ้น/ลงมือ (นับถ่วงน้ำหนักจากเกมพลิกล็อก) ให้ครบเท่านี้ถึงจะขยับมือ — แต้มสะสมถาวร ไม่รีเซ็ตเมื่อแพ้/ชนะสลับกัน

// คำนวณ Elo delta ของทั้งสองทีม (แยกออกมาเป็นฟังก์ชันล้วนๆ เพื่อเก็บค่าไว้แนบกับประวัติแมทช์ได้ด้วย)
function computeEloDeltas(players, teamAIds, teamBIds, winner) {
  const powerOf = (id) => players.find(p => p.id === id)?.power ?? 0;
  const avg = (ids) => ids.reduce((s, id) => s + powerOf(id), 0) / (ids.length || 1);
  const avgA = avg(teamAIds), avgB = avg(teamBIds);
  const expectedA = 1 / (1 + Math.pow(10, (avgB - avgA) / ELO_SCALE));
  const expectedB = 1 - expectedA;
  // ผลจริง: ชนะ=1, แพ้=0, เสมอ=0.5 — ทีมที่ถูกมองว่าเก่งกว่าจะได้พลังเพิ่มน้อยกว่า/เสียเยอะกว่าเมื่อเสมอกับทีมที่พลังต่ำกว่า ตาม ratio ที่คาดหวังไว้จริง
  const actualA = winner === 'A' ? 1 : winner === 'draw' ? 0.5 : 0;
  const actualB = 1 - actualA;
  const deltaA = Math.round(ELO_K * (actualA - expectedA));
  const deltaB = Math.round(ELO_K * (actualB - expectedB));
  return { deltaA, deltaB, expectedA, expectedB, actualA, actualB };
}

// ให้ "น้ำหนัก" ต่อแต้มขึ้น/ลงมือ: ปกติเกมละ 1 แต้ม แต่ถ้าเป็นการพลิกล็อก (โอกาสแพ้/ชนะที่คาดไว้ต่ำมาก) จะนับหนักขึ้น
// คล้ายระบบเกม MOBA ที่ชนะทีมแรงกว่ามากๆ ได้แต้มเลื่อนขั้นเร็วกว่าปกติ
function tierPointWeight(outcomeProbability) {
  if (outcomeProbability < 0.15) return 5;
  if (outcomeProbability < 0.30) return 3;
  return 1;
}

// อัปเดตแต้มสะสม + มือ (cls) ของผู้เล่นคนหนึ่งหลังจบเกม — แต้มสะสม "ถาวร" (ชนะ+, แพ้-) ไม่รีเซ็ตเมื่อผลสลับข้าง
// เช่น ชนะ 4 เกมรวด (+4) แล้วแพ้เกมที่ 5 (-1) เหลือ +3 ต่อยอดไปเรื่อยๆ จนกว่าจะแตะ ±TIER_POINT_THRESHOLD ถึงขยับมือ (แล้วรีเซ็ตกลับ 0)
function applyTierPoints(player, won, isDraw, expectedForThisOutcome) {
  let points = player.tierPoints || 0;
  let cls = player.cls;
  if (!isDraw) {
    const weight = tierPointWeight(expectedForThisOutcome);
    points += won ? weight : -weight;
  }
  const idx = TIERS.indexOf(cls);
  if (points >= TIER_POINT_THRESHOLD && idx < TIERS.length - 1) { cls = TIERS[idx + 1]; points = 0; }
  else if (points <= -TIER_POINT_THRESHOLD && idx > 0) { cls = TIERS[idx - 1]; points = 0; }
  return { points, cls };
}

// Elo-style MMR update after a match, scaled by the power gap between the two teams,
// บวกระบบแต้มสะสมถาวรที่ทำให้ "มือ" (cls) เปลี่ยนช้าและเสถียรกว่าพลัง (power) ที่ขยับทุกเกม
function updateEloForMatch(players, teamAIds, teamBIds, winner) {
  const { deltaA, deltaB, expectedA, expectedB, actualA, actualB } = computeEloDeltas(players, teamAIds, teamBIds, winner);
  const isDraw = winner === 'draw';
  return players.map(p => {
    if (teamAIds.includes(p.id)) {
      const { points, cls } = applyTierPoints(p, actualA === 1, isDraw, actualA === 1 ? expectedA : (1 - expectedA));
      return { ...p, power: Math.max(MIN_POWER, p.power + deltaA), tierPoints: points, cls };
    }
    if (teamBIds.includes(p.id)) {
      const { points, cls } = applyTierPoints(p, actualB === 1, isDraw, actualB === 1 ? expectedB : (1 - expectedB));
      return { ...p, power: Math.max(MIN_POWER, p.power + deltaB), tierPoints: points, cls };
    }
    return p;
  });
}

function computePairStats(matchRecords) {
  const result = {};
  const ensure = (id) => { if (!result[id]) result[id] = { mates: {}, opps: {} }; };
  matchRecords.forEach(rec => {
    if (!rec.winner || !rec.teamA || !rec.teamB) return;
    const outcomeA = rec.winner === 'A' ? 'win' : rec.winner === 'draw' ? 'draw' : 'loss';
    const outcomeB = rec.winner === 'B' ? 'win' : rec.winner === 'draw' ? 'draw' : 'loss';
    const bump = (id, key, group, outcome) => {
      ensure(id);
      result[id][group][key] = result[id][group][key] || { games: 0, wins: 0, draws: 0 };
      result[id][group][key].games += 1;
      if (outcome === 'win') result[id][group][key].wins += 1;
      if (outcome === 'draw') result[id][group][key].draws += 1;
    };
    rec.teamA.forEach(pid => {
      rec.teamA.filter(x => x !== pid).forEach(mate => bump(pid, mate, 'mates', outcomeA));
      rec.teamB.forEach(opp => bump(pid, opp, 'opps', outcomeA));
    });
    rec.teamB.forEach(pid => {
      rec.teamB.filter(x => x !== pid).forEach(mate => bump(pid, mate, 'mates', outcomeB));
      rec.teamA.forEach(opp => bump(pid, opp, 'opps', outcomeB));
    });
  });
  return result;
}

// จัดรูปแบบวันที่/เวลาตามโซนเวลาประเทศไทย (Asia/Bangkok) — ปี ค.ศ. ปกติ ไม่ใช่ปี พ.ศ.
function formatThaiDateTime(timestamp) {
  if (!timestamp) return '';
  return new Intl.DateTimeFormat('th-TH-u-ca-gregory', {
    timeZone: 'Asia/Bangkok',
    day: '2-digit', month: 'short', year: 'numeric',
    hour: '2-digit', minute: '2-digit', hour12: false,
  }).format(new Date(timestamp));
}
function formatThaiTime(timestamp) {
  if (!timestamp) return '';
  return new Intl.DateTimeFormat('th-TH-u-ca-gregory', {
    timeZone: 'Asia/Bangkok', hour: '2-digit', minute: '2-digit', hour12: false,
  }).format(new Date(timestamp));
}
// dayKey: 'YYYY-MM-DD' ตามเวลาไทย (ใช้จัดกลุ่มประวัติรายวัน)
function dayKeyOf(timestamp) {
  return new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Bangkok' }).format(new Date(timestamp));
}
function formatThaiDateLong(dayKey) {
  return new Intl.DateTimeFormat('th-TH-u-ca-gregory', {
    timeZone: 'UTC', day: '2-digit', month: 'long', year: 'numeric', weekday: 'long',
  }).format(new Date(dayKey + 'T00:00:00Z'));
}
function groupMatchesByDay(matchRecords) {
  const groups = {};
  matchRecords.forEach(r => {
    const key = dayKeyOf(r.timestamp);
    if (!groups[key]) groups[key] = [];
    groups[key].push(r);
  });
  return groups;
}

// ราคาที่ใช้จริงของแต่ละวัน: ถ้าวันนั้นเคยถูกตั้งราคาไว้ ใช้ราคานั้นตลอดไป (ล็อกไม่เปลี่ยนตามการแก้ไขในวันถัดๆ ไป)
// ถ้าวันนั้นยังไม่เคยตั้งราคาเลย (เช่นวันใหม่ที่ยังไม่ได้แก้ไข) ให้สืบราคาล่าสุดที่เคยตั้งไว้ก่อนหน้า ถ้าไม่เคยมีเลยค่อย fallback ไปค่าเริ่มต้น
function priceForDay(dailyPrices, dayKey) {
  if (dailyPrices[dayKey]) return dailyPrices[dayKey];
  const priorKeys = Object.keys(dailyPrices).filter(k => k < dayKey).sort();
  if (priorKeys.length) return dailyPrices[priorKeys[priorKeys.length - 1]];
  return { courtFee: DEFAULT_COURT_FEE, shuttlePrice: DEFAULT_SHUTTLE_PRICE };
}

function computeDues(matchRecords, dailyPrices) {
  const dues = {};
  // ค่าสนาม: คิดแค่ครั้งเดียวต่อผู้เล่นหนึ่งคน (เกมแรกที่เขาลงเล่นในวันนั้น)
  // ค่าลูก: คิดเต็มทุกเกมที่เขาเล่นจริง ไม่หารเฉลี่ย
  // ราคาที่ใช้ยึดตาม "วันที่เกมนั้นเล่นจริง" เสมอ — แก้ราคาวันนี้จะคำนวณใหม่ทุกเกมของวันนี้ แต่ไม่กระทบวันก่อนหน้าที่ปิดไปแล้ว
  const sorted = [...matchRecords].sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));
  const courtFeeCharged = new Set();
  sorted.forEach(rec => {
    const price = priceForDay(dailyPrices, dayKeyOf(rec.timestamp));
    const shuttleCost = rec.shuttlecocks * price.shuttlePrice;
    rec.playerIds.forEach(id => {
      dues[id] = dues[id] || { games: 0, shuttles: 0, courtFeePaid: 0, shuttleCost: 0, total: 0 };
      dues[id].games += 1;
      dues[id].shuttles += rec.shuttlecocks;
      dues[id].shuttleCost += shuttleCost;
      let cost = shuttleCost;
      if (!courtFeeCharged.has(id)) {
        dues[id].courtFeePaid += price.courtFee;
        cost += price.courtFee;
        courtFeeCharged.add(id);
      }
      dues[id].total += cost;
    });
  });
  return Object.entries(dues).map(([id, d]) => ({
    id: Number(id), games: d.games, shuttles: d.shuttles,
    courtFeePaid: Math.round(d.courtFeePaid), shuttleCost: Math.round(d.shuttleCost),
    total: Math.round(d.total),
  }));
}

/* ---------------------------------------------------------
   PROFILE MODAL
--------------------------------------------------------- */
function ProfileModal({ player, allPlayers, onClose, onToggleBlock, onSetPhoto, pairStats = {}, matchRecords = [] }) {
  const fileInputRef = React.useRef(null);
  const [showContact, setShowContact] = useState(false);
  React.useEffect(() => { setShowContact(false); }, [player?.id]);
  if (!player) return null;
  const winRate = Math.round((player.w / player.played) * 100) || 0;

  const nameOf = (id) => allPlayers.find(p => p.id === id)?.name || '?';
  const toRateList = (obj) => Object.entries(obj || {})
    .map(([id, d]) => ({
      id: Number(id), games: d.games, wins: d.wins, draws: d.draws || 0,
      losses: d.games - d.wins - (d.draws || 0),
      rate: d.games ? Math.round(((d.wins + (d.draws || 0) * 0.5) / d.games) * 100) : 0,
    }))
    .sort((a, b) => b.games - a.games);

  const mates = toRateList(pairStats[player.id]?.mates);
  const opps = toRateList(pairStats[player.id]?.opps);
  const bestDuoStat = mates.length > 0 ? [...mates].sort((a, b) => b.rate - a.rate || b.games - a.games)[0] : null;
  // คู่ปรับ = คนที่เรามีอัตราแพ้เยอะที่สุด (win rate ต่ำสุดตอนเจอกัน)
  const rivalStat = opps.length > 0 ? [...opps].sort((a, b) => a.rate - b.rate || b.games - a.games)[0] : null;

  const history = matchRecords
    .filter(r => r.playerIds?.includes(player.id))
    .sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0))
    .slice(0, 50)
    .map(r => {
      const inTeamA = r.teamA.includes(player.id);
      const myTeam = inTeamA ? r.teamA : r.teamB;
      const oppTeam = inTeamA ? r.teamB : r.teamA;
      const result = r.winner === 'draw' ? 'draw' : ((inTeamA && r.winner === 'A') || (!inTeamA && r.winner === 'B')) ? 'win' : 'loss';
      const teammateId = myTeam.find(id => id !== player.id);
      return { id: r.id, courtName: r.courtName, result, teammateId, oppTeam, playedAt: formatThaiDateTime(r.timestamp) };
    });

  const handlePhotoChange = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    compressImageFile(file)
      .then((dataUrl) => onSetPhoto(player.id, dataUrl))
      .catch(() => {}); // ถ้าบีบอัดไม่สำเร็จ ก็แค่ไม่เปลี่ยนรูป ไม่ทำแอปพัง
  };

  return (
    <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-slate-900 border-2 border-slate-700/60 rounded-2xl max-w-sm w-full p-6 relative max-h-[85vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
        <button onClick={onClose} className="absolute top-4 right-4 text-slate-300 hover:text-white"><X className="w-5 h-5" /></button>
        <div className="flex flex-col items-center text-center">
          <div className="relative mb-3">
            <div className="w-24 h-24 rounded-full bg-slate-950 border-4 border-slate-700/60 overflow-hidden flex items-center justify-center text-5xl">
              {player.photo ? <img src={player.photo} alt={player.name} className="w-full h-full object-cover" /> : player.avatar}
            </div>
            <button
              onClick={() => fileInputRef.current?.click()}
              className="absolute bottom-0 right-0 w-8 h-8 rounded-full bg-cyan-600 hover:bg-cyan-500 border-2 border-slate-700 flex items-center justify-center text-white shadow-lg"
              title="ถ่าย/อัปโหลดรูปโปรไฟล์"
            >
              <Camera className="w-4 h-4" />
            </button>
            <input ref={fileInputRef} type="file" accept="image/*" onChange={handlePhotoChange} className="hidden" />
          </div>
          <h2 className="text-2xl font-black text-white mb-2">{player.name}</h2>
          <span className={`px-2 py-0.5 rounded text-xs font-bold border-2 mb-3 ${clsColor(player.cls)}`}>มือ {player.cls}</span>

          {(player.fullName || player.phone) && (
            showContact ? (
              <div className="w-full bg-slate-900 border-2 border-slate-700/60 rounded-xl p-3 mb-4 text-sm text-left space-y-1">
                {player.fullName && <p className="text-slate-300"><span className="text-slate-300">ชื่อจริง-นามสกุล:</span> {player.fullName}</p>}
                {player.phone && <p className="text-slate-300"><span className="text-slate-300">เบอร์โทร:</span> {player.phone}</p>}
                <button onClick={() => setShowContact(false)} className="text-xs text-cyan-500 hover:text-cyan-400 mt-1">ซ่อนข้อมูลติดต่อ</button>
              </div>
            ) : (
              <button onClick={() => setShowContact(true)} className="text-xs text-cyan-500 hover:text-cyan-400 border-2 border-slate-700/60 rounded-full px-3 py-1 mb-4">
                ดูข้อมูลติดต่อ (ชื่อจริง/เบอร์โทร)
              </button>
            )
          )}
        </div>
        <div className="grid grid-cols-2 gap-3 mb-4">
          <div className="bg-slate-900 rounded-xl p-3 border-2 border-slate-700/50">
            <p className="text-xs text-slate-300 flex items-center gap-1"><Swords className="w-3 h-3" /> พลังรบ</p>
            <p className="text-xl font-black text-white">{player.power}</p>
          </div>
          <div className="bg-slate-900 rounded-xl p-3 border-2 border-slate-700/50">
            <p className="text-xs text-slate-300 flex items-center gap-1"><TrendingUp className="w-3 h-3" /> Win Rate</p>
            <p className="text-xl font-black text-cyan-600">{winRate}%</p>
          </div>
          <div className="bg-slate-900 rounded-xl p-3 border-2 border-slate-700/50">
            <p className="text-xs text-slate-300">คู่หูรู้ใจ</p>
            <p className="text-sm font-bold text-emerald-400">{bestDuoStat ? nameOf(bestDuoStat.id) : player.bestDuo}</p>
            {bestDuoStat && <p className="text-[11px] text-slate-300 font-mono">{bestDuoStat.rate}% ({bestDuoStat.wins}W-{bestDuoStat.losses}L{bestDuoStat.draws ? `-${bestDuoStat.draws}D` : ''})</p>}
          </div>
          <div className="bg-slate-900 rounded-xl p-3 border-2 border-slate-700/50">
            <p className="text-xs text-slate-300">คู่ปรับ</p>
            <p className="text-sm font-bold text-rose-400">{rivalStat ? nameOf(rivalStat.id) : player.rival}</p>
            {rivalStat && <p className="text-[11px] text-slate-300 font-mono">แพ้ {100 - rivalStat.rate}% ({rivalStat.losses}L-{rivalStat.wins}W{rivalStat.draws ? `-${rivalStat.draws}D` : ''})</p>}
          </div>
        </div>

        <div className="mb-4">
          <h3 className="text-sm font-bold text-white mb-2 flex items-center gap-2"><Clock className="w-4 h-4 text-cyan-600" /> ประวัติการแข่งย้อนหลัง (สูงสุด 50 เกม)</h3>
          {history.length === 0 ? (
            <p className="text-sm text-cyan-500">ยังไม่มีประวัติการแข่ง</p>
          ) : (
            <div className="space-y-1 max-h-96 overflow-y-auto pr-1">
              {history.map(h => (
                <div key={h.id} className="bg-slate-900 rounded-lg px-3 py-1.5 border-2 border-slate-700/50 text-sm">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-1.5 text-slate-300 truncate">
                      <span className="text-cyan-500 text-xs shrink-0">{h.courtName}</span>
                      {h.teammateId && <span className="truncate">คู่ {nameOf(h.teammateId)}</span>}
                      <span className="text-slate-300 text-xs shrink-0">vs {h.oppTeam.map(nameOf).join(', ')}</span>
                    </div>
                    <span className={`text-xs font-black shrink-0 ml-2 ${h.result === 'win' ? 'text-emerald-400' : h.result === 'draw' ? 'text-amber-400' : 'text-rose-400'}`}>{h.result === 'win' ? 'ชนะ' : h.result === 'draw' ? 'เสมอ' : 'แพ้'}</span>
                  </div>
                  {h.playedAt && <p className="text-[10px] text-slate-300 mt-0.5">{h.playedAt} น. (เวลาไทย)</p>}
                </div>
              ))}
            </div>
          )}
        </div>

        <div>
          <h3 className="text-sm font-bold text-white mb-2 flex items-center gap-2"><ShieldOff className="w-4 h-4 text-rose-400" /> บล็อกชั่วคราว (ไม่จับคู่เป็นทีมเดียวกัน — ยังลงคอร์ทเดียวกันได้)</h3>
          <div className="space-y-1.5 max-h-96 overflow-y-auto pr-1">
            {allPlayers.filter(p => p.id !== player.id).map(p => {
              const isBlocked = player.blocked.includes(p.id);
              return (
                <button key={p.id} onClick={() => onToggleBlock(player.id, p.id)}
                  className={`w-full flex items-center justify-between px-3 py-2 rounded-lg text-sm border-2 transition-colors ${isBlocked ? 'bg-rose-950/40 border-rose-500/50 text-rose-400' : 'bg-slate-950 border-slate-700/50 text-slate-300 hover:border-slate-600'}`}>
                  <span className="flex items-center gap-2">{p.avatar} {p.name}</span>
                  <span className="text-xs font-bold">{isBlocked ? 'บล็อกอยู่ ✕' : 'บล็อก'}</span>
                </button>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   CHECK-IN (home page — search & check in today's players)
--------------------------------------------------------- */
/* ---------------------------------------------------------
   ADD PLAYER — new member form (name, มือ, เพศ, รูปถ่าย)
--------------------------------------------------------- */
function PlayerFormModal({ mode = 'add', initial = null, onSubmit, onClose }) {
  const [name, setName] = useState(initial?.name || '');
  const [fullName, setFullName] = useState(initial?.fullName || '');
  const [phone, setPhone] = useState(initial?.phone || '');
  const [cls, setCls] = useState(initial?.cls || 'N');
  const [power, setPower] = useState(initial?.power ?? (TIER_BASE_POWER[initial?.cls || 'N'] + 50));
  const [gender, setGender] = useState(initial?.gender || 'M');
  const [photo, setPhoto] = useState(initial?.photo || null);
  const fileInputRef = React.useRef(null);

  const handlePhotoChange = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    compressImageFile(file)
      .then((dataUrl) => setPhoto(dataUrl))
      .catch(() => {}); // ถ้าบีบอัดไม่สำเร็จ ก็แค่ไม่เปลี่ยนรูป ไม่ทำแอปพัง
  };

  // เลือกมือเอง -> ปรับพลังรบไปกึ่งกลางของมือนั้นให้อัตโนมัติ
  const handleClsChange = (newCls) => {
    setCls(newCls);
    setPower(TIER_BASE_POWER[newCls] + 50);
  };

  // แก้พลังรบเอง -> ให้มืออัปเดตตามช่วงที่ตัวเลขนั้นตกอยู่โดยอัตโนมัติ
  const handlePowerChange = (value) => {
    const num = value === '' ? 0 : Number(value);
    setPower(num);
    setCls(clsFromPower(num));
  };

  const canSubmit = name.trim().length > 0;

  const handleSubmit = () => {
    if (!canSubmit) return;
    onSubmit({ name: name.trim(), fullName: fullName.trim(), phone: phone.trim(), cls, gender, photo, power });
  };

  return (
    <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-slate-900 border-2 border-slate-700/60 rounded-2xl max-w-sm w-full p-6 relative max-h-[85vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
        <button onClick={onClose} className="absolute top-4 right-4 text-slate-300 hover:text-white"><X className="w-5 h-5" /></button>
        <h3 className="text-lg font-black text-white mb-4">{mode === 'edit' ? 'แก้ไขข้อมูลสมาชิก' : 'เพิ่มสมาชิกใหม่'}</h3>

        <div className="flex flex-col items-center mb-4">
          <div className="relative mb-2">
            <div className="w-20 h-20 rounded-full bg-slate-950 border-4 border-slate-700/60 overflow-hidden flex items-center justify-center text-4xl">
              {photo ? <img src={photo} alt="" className="w-full h-full object-cover" /> : '🏸'}
            </div>
            <button
              onClick={() => fileInputRef.current?.click()}
              className="absolute bottom-0 right-0 w-7 h-7 rounded-full bg-cyan-600 hover:bg-cyan-500 border-2 border-slate-700 flex items-center justify-center text-white shadow-lg"
              title="ถ่าย/อัปโหลดรูปโปรไฟล์"
            >
              <Camera className="w-3.5 h-3.5" />
            </button>
            <input ref={fileInputRef} type="file" accept="image/*" onChange={handlePhotoChange} className="hidden" />
          </div>
        </div>

        <div className="space-y-3">
          <label className="block text-xs text-slate-300">
            ชื่อเล่น (แสดงในแอป)
            <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="กรอกชื่อเล่น"
              className="mt-1 w-full bg-slate-950 border-2 border-slate-700/60 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-cyan-500" />
          </label>
          <label className="block text-xs text-slate-300">
            ชื่อจริง-นามสกุล (ไม่บังคับ)
            <input type="text" value={fullName} onChange={(e) => setFullName(e.target.value)} placeholder="กรอกชื่อจริง-นามสกุล"
              className="mt-1 w-full bg-slate-950 border-2 border-slate-700/60 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-cyan-500" />
          </label>
          <label className="block text-xs text-slate-300">
            เบอร์โทรศัพท์ (ไม่บังคับ)
            <input type="tel" value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="0812345678"
              className="mt-1 w-full bg-slate-950 border-2 border-slate-700/60 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-cyan-500" />
          </label>
          <div className="grid grid-cols-2 gap-3">
            <label className="block text-xs text-slate-300">
              มือ
              <select value={cls} onChange={(e) => handleClsChange(e.target.value)}
                className="mt-1 w-full bg-slate-950 border-2 border-slate-700/60 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-cyan-500">
                {TIERS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </label>
            <label className="block text-xs text-slate-300">
              พลังรบ (ELO)
              <input type="number" value={power} onChange={(e) => handlePowerChange(e.target.value)}
                className="mt-1 w-full bg-slate-950 border-2 border-slate-700/60 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-cyan-500" />
            </label>
          </div>
          <p className="text-[10px] text-slate-300">แก้พลังรบแล้วมือจะขยับตามอัตโนมัติ (หรือเลือกมือแล้วพลังรบจะเด้งไปกึ่งกลางของมือนั้นแทน)</p>
          <label className="block text-xs text-slate-300">
            เพศ
            <div className="mt-1 grid grid-cols-2 gap-2">
              <button type="button" onClick={() => setGender('M')} className={`py-2 rounded-lg text-sm font-bold border-2 ${gender === 'M' ? 'bg-cyan-600 border-cyan-500 text-white' : 'bg-slate-950 border-slate-700/60 text-slate-300'}`}>ชาย</button>
              <button type="button" onClick={() => setGender('F')} className={`py-2 rounded-lg text-sm font-bold border-2 ${gender === 'F' ? 'bg-cyan-600 border-cyan-500 text-white' : 'bg-slate-950 border-slate-700/60 text-slate-300'}`}>หญิง</button>
            </div>
          </label>
        </div>

        <button onClick={handleSubmit} disabled={!canSubmit}
          className="mt-5 w-full bg-cyan-600 hover:bg-cyan-500 disabled:bg-slate-800 disabled:text-slate-300 text-white font-bold py-2.5 rounded-lg flex items-center justify-center gap-2">
          {mode === 'edit' ? <><CheckCircle2 className="w-4 h-4" /> บันทึกการแก้ไข</> : <><Plus className="w-4 h-4" /> เพิ่มสมาชิก</>}
        </button>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   DELETE CONFIRM — must retype a random 5-digit code
--------------------------------------------------------- */
function DeleteConfirmModal({ player, onConfirm, onClose }) {
  const [code] = useState(() => String(Math.floor(10000 + Math.random() * 90000)));
  const [input, setInput] = useState('');
  const matches = input.trim() === code;

  return (
    <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-slate-900 border-2 border-rose-600 rounded-2xl max-w-sm w-full p-6 relative" onClick={(e) => e.stopPropagation()}>
        <button onClick={onClose} className="absolute top-4 right-4 text-slate-300 hover:text-white"><X className="w-5 h-5" /></button>
        <div className="flex items-center gap-3 mb-3">
          <Avatar player={player} size="w-11 h-11" textSize="text-xl" />
          <div>
            <p className="text-sm text-slate-300">ยืนยันการลบสมาชิก</p>
            <p className="font-bold text-white">{player.name}</p>
          </div>
        </div>
        <p className="text-xs text-rose-400 mb-4">การลบไม่สามารถย้อนกลับได้ กรุณาพิมพ์รหัส 5 หลักด้านล่างให้ตรงกันเพื่อยืนยัน</p>

        <div className="bg-slate-950 border-2 border-slate-700/60 rounded-xl py-4 text-center mb-4 select-none">
          <span className="text-3xl font-black tracking-[0.4em] text-cyan-600 font-mono">{code}</span>
        </div>

        <input
          type="text"
          inputMode="numeric"
          value={input}
          onChange={(e) => setInput(e.target.value.replace(/[^0-9]/g, '').slice(0, 5))}
          placeholder="พิมพ์รหัสที่เห็นด้านบน"
          className="w-full bg-slate-950 border-2 border-slate-700/60 rounded-lg px-3 py-2.5 text-center text-lg tracking-widest font-mono text-white focus:outline-none focus:border-rose-500 mb-4"
        />

        <div className="flex gap-2">
          <button onClick={onClose} className="flex-1 py-2.5 rounded-lg text-sm font-bold border-2 border-slate-700 text-slate-300 hover:bg-slate-800">ยกเลิก</button>
          <button onClick={() => matches && onConfirm()} disabled={!matches}
            className="flex-1 py-2.5 rounded-lg text-sm font-bold bg-rose-600 hover:bg-rose-500 disabled:bg-slate-800 disabled:text-slate-300 text-white flex items-center justify-center gap-1">
            <Trash2 className="w-4 h-4" /> ยืนยันลบ
          </button>
        </div>
      </div>
    </div>
  );
}

function CheckInPage({ players, checkedInIds, onToggleCheckIn, onOpenProfile, onAddPlayer, onEditPlayer, onDeletePlayer }) {
  const [query, setQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState(null);
  const [deleteTarget, setDeleteTarget] = useState(null);
  const filtered = players.filter(p => p.name.toLowerCase().includes(query.trim().toLowerCase()));
  const checkedInPlayers = players.filter(p => checkedInIds.includes(p.id));

  const confirmDelete = () => {
    if (!deleteTarget) return;
    onDeletePlayer(deleteTarget.id);
    setDeleteTarget(null);
  };

  return (
    <div className="space-y-8">
      <div>
        <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
          <h3 className="text-lg font-black uppercase tracking-wider text-white flex items-center gap-2">
            <span className="w-2 h-5 bg-cyan-600 rounded-sm" /> เช็คอินสมาชิกวันนี้
          </h3>
          <button onClick={() => setShowAddModal(true)}
            className="bg-cyan-600 hover:bg-cyan-500 text-white text-sm font-bold px-3.5 py-2.5 rounded-lg flex items-center gap-1.5">
            <Plus className="w-4 h-4" /> เพิ่มสมาชิกใหม่
          </button>
        </div>
        <div className="relative mb-4">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-cyan-500" />
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="พิมพ์ชื่อเพื่อค้นหา..."
            className="w-full bg-slate-900 border-2 border-slate-700/60 rounded-full py-2.5 pl-10 pr-4 text-sm text-white placeholder-slate-600 focus:outline-none focus:border-cyan-500 transition-colors"
          />
        </div>
        <div className="space-y-2">
          {filtered.map(p => {
            const isIn = checkedInIds.includes(p.id);
            return (
              <div key={p.id} className={`flex items-center justify-between p-3 rounded-xl border-2 transition-colors ${isIn ? 'bg-cyan-950/40 border-cyan-500/50' : 'bg-slate-900 border-slate-700/50'}`}>
                <div className="flex items-center gap-3">
                  <Avatar player={p} size="w-11 h-11" textSize="text-xl" />
                  <div>
                    <p className="font-bold text-sm text-white">{p.name}</p>
                    <p className="text-xs text-cyan-500">มือ {p.cls}</p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <button onClick={() => onOpenProfile(p.id)} className="text-cyan-500 hover:text-cyan-400"><Info className="w-4 h-4" /></button>
                  <button onClick={() => setEditTarget(p)} className="text-cyan-500 hover:text-cyan-400"><Pencil className="w-4 h-4" /></button>
                  <button onClick={() => setDeleteTarget(p)}
                    className="text-xs font-bold px-2 py-1.5 rounded-lg border-2 flex items-center gap-1 text-rose-400 border-rose-500/30 bg-rose-500/10 hover:bg-rose-500/20">
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                  <button
                    onClick={() => onToggleCheckIn(p.id)}
                    className={`px-3 py-1.5 rounded-lg text-xs font-bold border-2 flex items-center gap-1 ${isIn ? 'bg-cyan-500/10 border-cyan-500/40 text-cyan-400' : 'bg-cyan-500/10 border-cyan-500/40 text-cyan-400 hover:bg-cyan-500/20'}`}
                  >
                    {isIn ? <><CheckCircle2 className="w-4 h-4" /> เช็คอินแล้ว</> : <><Plus className="w-4 h-4" /> เพิ่ม</>}
                  </button>
                </div>
              </div>
            );
          })}
          {filtered.length === 0 && <p className="text-center text-cyan-500 text-sm py-6">ไม่พบชื่อนี้</p>}
        </div>
      </div>

      <div>
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-lg font-black uppercase tracking-wider text-white flex items-center gap-2"><span className="w-2 h-5 bg-cyan-500 rounded-sm" /> วันนี้เช็คอินแล้ว</h3>
          <span className="text-sm text-slate-300">{checkedInPlayers.length} คน</span>
        </div>
        {checkedInPlayers.length === 0 ? (
          <div className="flex items-center gap-3 bg-slate-900 border-2 border-slate-700 rounded-2xl p-4">
            <img src={MASCOT_GIRL} alt="" className="w-16 h-16 object-contain shrink-0 mascot-wiggle" />
            <p className="text-sm text-slate-300">ยังไม่มีใครเช็คอิน — ค้นหาชื่อด้านบนแล้วกด "เพิ่ม" ได้เลย</p>
          </div>
        ) : (
          <div className="flex flex-wrap gap-2">
            {checkedInPlayers.map(p => (
              <span key={p.id} className="flex items-center gap-1.5 text-sm bg-slate-900 border-2 border-cyan-500/40 px-3 py-1.5 rounded-full text-cyan-400">
                {p.avatar} {p.name}
                <button onClick={() => onToggleCheckIn(p.id)} className="text-cyan-500 hover:text-rose-400"><X className="w-3.5 h-3.5" /></button>
              </span>
            ))}
          </div>
        )}
        <p className="text-xs text-cyan-500 mt-3">คนที่เช็คอินแล้วจะไปโผล่ในคิว "รอลงเกม" ที่หน้าแอดมินให้อัตโนมัติ</p>
      </div>

      {showAddModal && (
        <PlayerFormModal
          mode="add"
          onSubmit={(data) => { onAddPlayer(data); setShowAddModal(false); }}
          onClose={() => setShowAddModal(false)}
        />
      )}
      {editTarget && (
        <PlayerFormModal
          mode="edit"
          initial={editTarget}
          onSubmit={(data) => { onEditPlayer(editTarget.id, data); setEditTarget(null); }}
          onClose={() => setEditTarget(null)}
        />
      )}
      {deleteTarget && (
        <DeleteConfirmModal
          player={deleteTarget}
          onConfirm={confirmDelete}
          onClose={() => setDeleteTarget(null)}
        />
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   DELETE DAY CONFIRM — same 5-digit code pattern, for deleting
   a whole day's worth of history records
--------------------------------------------------------- */
function DeleteDayConfirmModal({ dayLabel, onConfirm, onClose }) {
  const [code] = useState(() => String(Math.floor(10000 + Math.random() * 90000)));
  const [input, setInput] = useState('');
  const matches = input.trim() === code;

  return (
    <div className="fixed inset-0 bg-black/90 z-[110] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-slate-900 border-2 border-rose-600 rounded-2xl max-w-sm w-full p-6 relative" onClick={(e) => e.stopPropagation()}>
        <button onClick={onClose} className="absolute top-4 right-4 text-slate-300 hover:text-white"><X className="w-5 h-5" /></button>
        <div className="mb-3">
          <p className="text-sm text-slate-300">ยืนยันการลบประวัติทั้งวัน</p>
          <p className="font-bold text-white">{dayLabel}</p>
        </div>
        <p className="text-xs text-rose-400 mb-4">จะลบทุกเกม ทุกยอดเงิน และสถิติของวันนี้ทั้งหมด — การลบไม่สามารถย้อนกลับได้ กรุณาพิมพ์รหัส 5 หลักด้านล่างให้ตรงกันเพื่อยืนยัน</p>

        <div className="bg-slate-950 border-2 border-slate-700/60 rounded-xl py-4 text-center mb-4 select-none">
          <span className="text-3xl font-black tracking-[0.4em] text-cyan-600 font-mono">{code}</span>
        </div>

        <input
          type="text"
          inputMode="numeric"
          value={input}
          onChange={(e) => setInput(e.target.value.replace(/[^0-9]/g, '').slice(0, 5))}
          placeholder="พิมพ์รหัสที่เห็นด้านบน"
          className="w-full bg-slate-950 border-2 border-slate-700/60 rounded-lg px-3 py-2.5 text-center text-lg tracking-widest font-mono text-white focus:outline-none focus:border-rose-500 mb-4"
        />

        <div className="flex gap-2">
          <button onClick={onClose} className="flex-1 py-2.5 rounded-lg text-sm font-bold border-2 border-slate-700 text-slate-300 hover:bg-slate-800">ยกเลิก</button>
          <button onClick={() => matches && onConfirm()} disabled={!matches}
            className="flex-1 py-2.5 rounded-lg text-sm font-bold bg-rose-600 hover:bg-rose-500 disabled:bg-slate-800 disabled:text-slate-300 text-white flex items-center justify-center gap-1">
            <Trash2 className="w-4 h-4" /> ยืนยันลบทั้งวัน
          </button>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   HISTORY — past days, each browsable with full match + money detail
--------------------------------------------------------- */
/* ---------------------------------------------------------
   PASSWORD GATE — must unlock before using the app.
   Default password: 123456. Masterkey (110200) always works and can also
   be used to set a new password.
--------------------------------------------------------- */
const MASTER_KEY = '110200';
const DEFAULT_PASSWORD = '123456';

function PasswordGate({ appPassword, onUnlock, onChangePassword }) {
  const [view, setView] = useState('login'); // 'login' | 'change' | 'forgot'
  const [input, setInput] = useState('');
  const [error, setError] = useState('');

  const [oldInput, setOldInput] = useState('');
  const [newPass1, setNewPass1] = useState('');
  const [newPass2, setNewPass2] = useState('');
  const [changeError, setChangeError] = useState('');
  const [changeSuccess, setChangeSuccess] = useState(false);

  const [masterInput, setMasterInput] = useState('');
  const [forgotPass1, setForgotPass1] = useState('');
  const [forgotPass2, setForgotPass2] = useState('');
  const [forgotError, setForgotError] = useState('');
  const [forgotSuccess, setForgotSuccess] = useState(false);

  const resetAllForms = () => {
    setInput(''); setError('');
    setOldInput(''); setNewPass1(''); setNewPass2(''); setChangeError(''); setChangeSuccess(false);
    setMasterInput(''); setForgotPass1(''); setForgotPass2(''); setForgotError(''); setForgotSuccess(false);
  };

  const goTo = (v) => { resetAllForms(); setView(v); };

  const handleLogin = () => {
    if (input === appPassword || input === MASTER_KEY) {
      onUnlock();
    } else {
      setError('รหัสผ่านไม่ถูกต้อง');
    }
  };

  // เปลี่ยนรหัสผ่าน — ต้องยืนยันรหัสผ่านเดิมให้ถูกก่อน (ใช้ตอนยังจำรหัสเดิมได้)
  const handleChangePassword = () => {
    setChangeError('');
    if (oldInput !== appPassword) { setChangeError('รหัสผ่านเดิมไม่ถูกต้อง'); return; }
    if (!newPass1 || newPass1.length < 4) { setChangeError('รหัสผ่านใหม่สั้นเกินไป (อย่างน้อย 4 ตัว)'); return; }
    if (newPass1 !== newPass2) { setChangeError('รหัสผ่านใหม่ไม่ตรงกัน'); return; }
    onChangePassword(newPass1);
    setChangeSuccess(true);
    setTimeout(() => goTo('login'), 1500);
  };

  // ลืมรหัสผ่าน — ใช้ Masterkey แทนรหัสผ่านเดิม (ใช้เฉพาะตอนจำรหัสเดิมไม่ได้)
  const handleForgotPassword = () => {
    setForgotError('');
    if (masterInput !== MASTER_KEY) { setForgotError('Masterkey ไม่ถูกต้อง'); return; }
    if (!forgotPass1 || forgotPass1.length < 4) { setForgotError('รหัสผ่านใหม่สั้นเกินไป (อย่างน้อย 4 ตัว)'); return; }
    if (forgotPass1 !== forgotPass2) { setForgotError('รหัสผ่านใหม่ไม่ตรงกัน'); return; }
    onChangePassword(forgotPass1);
    setForgotSuccess(true);
    setTimeout(() => goTo('login'), 1500);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white font-sans flex items-center justify-center p-4">
      <style dangerouslySetInnerHTML={{ __html: `
        @import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;800&family=Kalam:wght@400;700&display=swap');
        h1, h2 { font-family: 'Baloo 2', 'Kalam', sans-serif; }
      `}} />
      <div className="bg-slate-900 border-2 border-slate-700 rounded-2xl max-w-sm w-full p-6">
        <div className="flex flex-col items-center mb-6">
          <Logo />
        </div>

        {view === 'login' && (
          <>
            <h2 className="text-lg font-bold text-center mb-4 text-white">กรอกรหัสผ่านเพื่อเข้าใช้งาน</h2>
            <input
              type="password"
              value={input}
              onChange={(e) => { setInput(e.target.value); setError(''); }}
              onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
              placeholder="รหัสผ่าน"
              className="w-full bg-slate-950 border-2 border-slate-700 rounded-lg px-3 py-2.5 text-center text-lg tracking-widest mb-2 text-white focus:outline-none focus:border-cyan-500"
            />
            {error && <p className="text-rose-400 text-sm text-center mb-2">{error}</p>}
            <button onClick={handleLogin} className="w-full bg-cyan-600 hover:bg-cyan-500 text-white font-bold py-2.5 rounded-lg mb-3">
              เข้าสู่ระบบ
            </button>
            <div className="flex items-center justify-center gap-4">
              <button onClick={() => goTo('change')} className="text-xs text-cyan-400 hover:text-cyan-300">เปลี่ยนรหัสผ่าน</button>
              <span className="text-slate-700">|</span>
              <button onClick={() => goTo('forgot')} className="text-xs text-slate-400 hover:text-slate-300">ลืมรหัสผ่าน?</button>
            </div>
          </>
        )}

        {view === 'change' && (
          <>
            <h2 className="text-lg font-bold text-center mb-4 text-white">เปลี่ยนรหัสผ่าน</h2>
            {changeSuccess ? (
              <p className="text-emerald-400 text-center py-4 font-bold">เปลี่ยนรหัสผ่านสำเร็จ!</p>
            ) : (
              <div className="space-y-2">
                <input type="password" value={oldInput} onChange={(e) => setOldInput(e.target.value)}
                  placeholder="รหัสผ่านเดิม" className="w-full bg-slate-950 border-2 border-slate-700 rounded-lg px-3 py-2.5 text-center text-white focus:outline-none focus:border-cyan-500" />
                <input type="password" value={newPass1} onChange={(e) => setNewPass1(e.target.value)}
                  placeholder="รหัสผ่านใหม่" className="w-full bg-slate-950 border-2 border-slate-700 rounded-lg px-3 py-2.5 text-center text-white focus:outline-none focus:border-cyan-500" />
                <input type="password" value={newPass2} onChange={(e) => setNewPass2(e.target.value)}
                  placeholder="ยืนยันรหัสผ่านใหม่" className="w-full bg-slate-950 border-2 border-slate-700 rounded-lg px-3 py-2.5 text-center text-white focus:outline-none focus:border-cyan-500" />
                {changeError && <p className="text-rose-400 text-sm text-center">{changeError}</p>}
                <button onClick={handleChangePassword} className="w-full bg-cyan-600 hover:bg-cyan-500 text-white font-bold py-2.5 rounded-lg">
                  บันทึกรหัสผ่านใหม่
                </button>
              </div>
            )}
            <button onClick={() => goTo('login')} className="w-full text-xs text-slate-400 hover:text-slate-300 mt-3 text-center">
              กลับไปหน้าเข้าสู่ระบบ
            </button>
          </>
        )}

        {view === 'forgot' && (
          <>
            <h2 className="text-lg font-bold text-center mb-4 text-white">ลืมรหัสผ่าน</h2>
            {forgotSuccess ? (
              <p className="text-emerald-400 text-center py-4 font-bold">ตั้งรหัสผ่านใหม่สำเร็จ!</p>
            ) : (
              <div className="space-y-2">
                <input type="password" value={masterInput} onChange={(e) => setMasterInput(e.target.value)}
                  placeholder="Masterkey" className="w-full bg-slate-950 border-2 border-slate-700 rounded-lg px-3 py-2.5 text-center text-white focus:outline-none focus:border-cyan-500" />
                <input type="password" value={forgotPass1} onChange={(e) => setForgotPass1(e.target.value)}
                  placeholder="รหัสผ่านใหม่" className="w-full bg-slate-950 border-2 border-slate-700 rounded-lg px-3 py-2.5 text-center text-white focus:outline-none focus:border-cyan-500" />
                <input type="password" value={forgotPass2} onChange={(e) => setForgotPass2(e.target.value)}
                  placeholder="ยืนยันรหัสผ่านใหม่" className="w-full bg-slate-950 border-2 border-slate-700 rounded-lg px-3 py-2.5 text-center text-white focus:outline-none focus:border-cyan-500" />
                {forgotError && <p className="text-rose-400 text-sm text-center">{forgotError}</p>}
                <button onClick={handleForgotPassword} className="w-full bg-cyan-600 hover:bg-cyan-500 text-white font-bold py-2.5 rounded-lg">
                  ตั้งรหัสผ่านใหม่
                </button>
              </div>
            )}
            <button onClick={() => goTo('login')} className="w-full text-xs text-slate-400 hover:text-slate-300 mt-3 text-center">
              กลับไปหน้าเข้าสู่ระบบ
            </button>
          </>
        )}
      </div>
    </div>
  );
}

function DayDetailModal({ dayKey, records, players, onClose, onEditResult, dailyPrices, onDeleteDay }) {
  const [editingId, setEditingId] = useState(null);
  const [showDeleteDay, setShowDeleteDay] = useState(false);
  const dues = computeDues(records, dailyPrices).map(d => ({ ...d, player: players.find(p => p.id === d.id) })).filter(d => d.player);
  const netEloChange = (playerId) => records.reduce((sum, r) => sum + (r.powerDeltas?.[playerId] || 0), 0);
  const totalMoney = dues.reduce((s, d) => s + d.total, 0);
  const totalShuttles = records.reduce((s, r) => s + r.shuttlecocks, 0);
  const distinctPlayerIds = [...new Set(records.flatMap(r => r.playerIds))];
  const sortedRecords = [...records].sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));

  const nameOf = (id) => players.find(p => p.id === id)?.name || '?';
  const teamNames = (ids) => ids.map(nameOf).join(' + ');
  const courtNumberOf = (r) => (r.courtId || '').replace(/\D/g, '') || (r.courtName || '').replace(/\D/g, '') || '?';

  return (
    <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-slate-900 border-2 border-slate-700/60 rounded-2xl max-w-2xl w-full p-6 relative max-h-[85vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
        <button onClick={onClose} className="absolute top-4 right-4 text-slate-300 hover:text-white"><X className="w-5 h-5" /></button>
        <div className="flex items-start justify-between gap-3 pr-8 mb-1">
          <h2 className="text-lg font-black text-white">{formatThaiDateLong(dayKey)}</h2>
          <button onClick={() => setShowDeleteDay(true)} className="shrink-0 text-xs font-bold px-2.5 py-1.5 rounded-lg border-2 border-rose-600/60 text-rose-400 hover:bg-rose-950/40 flex items-center gap-1">
            <Trash2 className="w-3.5 h-3.5" /> ลบทั้งวัน
          </button>
        </div>
        <p className="text-xs text-slate-300 mb-4">สรุปการจัดก๊วนวันนี้</p>


        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
          <div className="bg-slate-950 rounded-xl p-3 border-2 border-slate-700/60 text-center">
            <Users className="w-4 h-4 text-cyan-600 mx-auto mb-1" />
            <p className="text-lg font-black text-white">{distinctPlayerIds.length}</p>
            <p className="text-[10px] text-slate-300">ผู้เล่น</p>
          </div>
          <div className="bg-slate-950 rounded-xl p-3 border-2 border-slate-700/60 text-center">
            <LayoutGrid className="w-4 h-4 text-cyan-600 mx-auto mb-1" />
            <p className="text-lg font-black text-white">{records.length}</p>
            <p className="text-[10px] text-slate-300">เกม</p>
          </div>
          <div className="bg-slate-950 rounded-xl p-3 border-2 border-slate-700/60 text-center">
            <span className="block text-sm mb-1">🏸</span>
            <p className="text-lg font-black text-white">{totalShuttles}</p>
            <p className="text-[10px] text-slate-300">ลูกแบด</p>
          </div>
          <div className="bg-slate-950 rounded-xl p-3 border-2 border-slate-700/60 text-center">
            <Wallet className="w-4 h-4 text-cyan-600 mx-auto mb-1" />
            <p className="text-lg font-black text-cyan-600">฿{totalMoney}</p>
            <p className="text-[10px] text-slate-300">ยอดรวม</p>
          </div>
        </div>

        <h3 className="text-sm font-bold text-white mb-2 flex items-center gap-2"><span className="w-2 h-4 bg-cyan-600 rounded-sm" /> เกมทั้งหมด</h3>
        <div className="space-y-2 mb-6 max-h-96 overflow-y-auto pr-1">
          {sortedRecords.map((r, idx) => (
            <div key={r.id} className="bg-slate-950 border-2 border-slate-700/60 rounded-xl p-3 text-sm">
              <div className="flex items-center justify-between mb-1.5">
                <span className="text-cyan-600 text-xs font-black">เกม {idx + 1} <span className="text-slate-300 font-normal">· สนาม {courtNumberOf(r)}</span></span>
                <span className="text-slate-300 text-xs">{formatThaiTime(r.timestamp)} น. · 🏸 {r.shuttlecocks}</span>
              </div>
              <div className="flex items-center justify-between flex-wrap gap-2">
                <span className={`text-xs ${r.winner === 'A' ? 'font-bold text-red-400' : 'text-slate-300'}`}>{TEAM.A.name}: {teamNames(r.teamA)}</span>
                <span className="text-slate-300 text-xs">vs</span>
                <span className={`text-xs ${r.winner === 'B' ? 'font-bold text-blue-400' : 'text-slate-300'}`}>{TEAM.B.name}: {teamNames(r.teamB)}</span>
                <span className={`text-xs font-black ml-auto ${r.winner === 'draw' ? 'text-amber-400' : 'text-emerald-400'}`}>
                  {r.winner === 'draw' ? 'เสมอ' : r.winner === 'A' ? `${TEAM.A.name}ชนะ` : `${TEAM.B.name}ชนะ`}
                </span>
                <button onClick={() => setEditingId(editingId === r.id ? null : r.id)} className="text-slate-300 hover:text-cyan-600">
                  <Pencil className="w-3.5 h-3.5" />
                </button>
              </div>
              {editingId === r.id && (
                <div className="mt-2.5 pt-2.5 border-t border-slate-700/60 flex items-center gap-1.5 flex-wrap">
                  <span className="text-[10px] text-slate-300">แก้ผลเป็น:</span>
                  <button onClick={() => { onEditResult(r.id, 'A'); setEditingId(null); }} className="px-2.5 py-1 rounded-lg text-[11px] font-bold border-2 border-red-500/50 bg-red-950/40 text-red-400 hover:bg-red-600 hover:text-white">{TEAM.A.name}ชนะ</button>
                  <button onClick={() => { onEditResult(r.id, 'B'); setEditingId(null); }} className="px-2.5 py-1 rounded-lg text-[11px] font-bold border-2 border-blue-500/50 bg-blue-950/40 text-blue-400 hover:bg-blue-600 hover:text-white">{TEAM.B.name}ชนะ</button>
                  <button onClick={() => { onEditResult(r.id, 'draw'); setEditingId(null); }} className="px-2.5 py-1 rounded-lg text-[11px] font-bold border-2 border-amber-500/50 bg-slate-950 text-amber-400 hover:bg-amber-600 hover:text-white">เสมอ</button>
                  <button onClick={() => setEditingId(null)} className="text-slate-300 hover:text-slate-300 ml-1"><X className="w-3.5 h-3.5" /></button>
                </div>
              )}
            </div>
          ))}
        </div>

        <h3 className="text-sm font-bold text-white mb-2 flex items-center gap-2"><span className="w-2 h-4 bg-cyan-600 rounded-sm" /> สรุปยอดต่อคน</h3>
        <div className="space-y-1.5 max-h-96 overflow-y-auto pr-1">
          {dues.map(d => {
            const change = netEloChange(d.player.id);
            return (
              <div key={d.player.id} className="flex items-center justify-between bg-slate-950 rounded-lg px-3 py-2 border-2 border-slate-700/60 text-sm">
                <span className="flex items-center gap-2 text-slate-200">
                  <Avatar player={d.player} size="w-7 h-7" textSize="text-sm" /> {d.player.name}
                  {change !== 0 && (
                    <span className={`text-xs font-bold ${change > 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                      ({change > 0 ? '+' : ''}{change})
                    </span>
                  )}
                </span>
                <span className="text-cyan-600 font-mono text-xs">{d.games} เกม = ฿{d.total}</span>
              </div>
            );
          })}
        </div>
      </div>
      {showDeleteDay && (
        <DeleteDayConfirmModal
          dayLabel={formatThaiDateLong(dayKey)}
          onConfirm={() => { onDeleteDay(dayKey); setShowDeleteDay(false); onClose(); }}
          onClose={() => setShowDeleteDay(false)}
        />
      )}
    </div>
  );
}

function HistoryPage({ matchRecords, players, onEditResult, dailyPrices, onDeleteDay }) {
  const [selectedDay, setSelectedDay] = useState(null);
  const groups = groupMatchesByDay(matchRecords);
  const days = Object.keys(groups).sort((a, b) => b.localeCompare(a));

  return (
    <div>
      <h3 className="text-lg font-black uppercase tracking-wider text-white flex items-center gap-2 mb-4">
        <span className="w-2 h-5 bg-cyan-600 rounded-sm" /> ประวัติการจัดก๊วน
      </h3>
      {days.length === 0 ? (
        <div className="flex flex-col items-center gap-2 py-10">
          <img src={MASCOT_SOCKS} alt="" className="w-16 h-16 object-contain opacity-80" />
          <p className="text-sm text-cyan-600 text-center">ยังไม่มีประวัติการแข่งเลย — พอเล่นจบเกมแรกแล้วจะเริ่มบันทึกไว้ที่นี่ค่ะ</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {days.map(day => {
            const records = groups[day];
            const dues = computeDues(records, dailyPrices);
            const totalMoney = dues.reduce((s, d) => s + d.total, 0);
            const totalShuttles = records.reduce((s, r) => s + r.shuttlecocks, 0);
            const distinctPlayerIds = new Set(records.flatMap(r => r.playerIds));
            return (
              <button key={day} onClick={() => setSelectedDay(day)}
                className="text-left bg-slate-900 border-2 border-slate-700/60 hover:border-cyan-500/50 rounded-2xl p-4 transition-colors">
                <p className="font-bold text-white text-sm mb-3">{formatThaiDateLong(day)}</p>
                <div className="grid grid-cols-3 gap-2 text-center">
                  <div>
                    <p className="text-lg font-black text-cyan-600">{distinctPlayerIds.size}</p>
                    <p className="text-[10px] text-slate-300">ผู้เล่น</p>
                  </div>
                  <div>
                    <p className="text-lg font-black text-cyan-600">{records.length}</p>
                    <p className="text-[10px] text-slate-300">เกม</p>
                  </div>
                  <div>
                    <p className="text-lg font-black text-cyan-600">{totalShuttles}</p>
                    <p className="text-[10px] text-slate-300">ลูกแบด</p>
                  </div>
                </div>
                <div className="mt-3 pt-3 border-t border-slate-700/50 flex items-center justify-between">
                  <span className="text-xs text-slate-300">ยอดรวม</span>
                  <span className="text-white font-mono font-bold">฿{totalMoney}</span>
                </div>
              </button>
            );
          })}
        </div>
      )}

      {selectedDay && (
        <DayDetailModal dayKey={selectedDay} records={groups[selectedDay]} players={players} onClose={() => setSelectedDay(null)} onEditResult={onEditResult} dailyPrices={dailyPrices} onDeleteDay={onDeleteDay} />
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   LEADERBOARD
--------------------------------------------------------- */
function LeaderboardPage({ players, attendance }) {
  const [sortBy, setSortBy] = useState('power'); // 'power' | 'cls' | 'winrate' | 'attendance' | 'name'
  const [sortDir, setSortDir] = useState('desc'); // 'desc' | 'asc'

  const attendanceCount = (id) => Object.keys(attendance[id] || {}).length;
  const winRateOf = (p) => (p.played ? p.w / p.played : 0);

  const sortOptions = [
    { key: 'power', label: 'พลัง' },
    { key: 'cls', label: 'มือ' },
    { key: 'winrate', label: 'W/L' },
    { key: 'attendance', label: 'เข้าร่วม' },
    { key: 'name', label: 'ชื่อ ก-ฮ' },
  ];

  const sorted = [...players].sort((a, b) => {
    let cmp = 0;
    if (sortBy === 'power') cmp = a.power - b.power;
    else if (sortBy === 'cls') cmp = TIERS.indexOf(a.cls) - TIERS.indexOf(b.cls);
    else if (sortBy === 'winrate') cmp = winRateOf(a) - winRateOf(b);
    else if (sortBy === 'attendance') cmp = attendanceCount(a.id) - attendanceCount(b.id);
    else if (sortBy === 'name') cmp = a.name.localeCompare(b.name, 'th');
    return sortDir === 'desc' ? -cmp : cmp;
  });

  return (
    <div className="bg-slate-900 border-2 border-slate-700/60 rounded-2xl overflow-hidden">
      <div className="bg-slate-950 p-4 border-b border-slate-700/50 space-y-3">
        <h3 className="font-bold text-white flex items-center gap-2"><Trophy className="w-5 h-5 text-cyan-600" /> ทำเนียบเจ้ายุทธภพ</h3>
        <div className="flex items-center gap-2 flex-wrap">
          {sortOptions.map(opt => (
            <button key={opt.key} onClick={() => setSortBy(opt.key)}
              className={`px-2.5 py-1 rounded-full text-xs font-bold border-2 ${sortBy === opt.key ? 'bg-cyan-600 border-cyan-500 text-white' : 'bg-slate-900 border-slate-700/60 text-slate-300 hover:border-cyan-500/50'}`}>
              {opt.label}
            </button>
          ))}
          <button onClick={() => setSortDir(d => d === 'desc' ? 'asc' : 'desc')}
            className="ml-auto px-2.5 py-1 rounded-full text-xs font-bold border-2 border-slate-700/60 bg-slate-900 text-cyan-400 hover:border-cyan-500/50 flex items-center gap-1">
            <RefreshCw className="w-3.5 h-3.5" /> {sortDir === 'desc' ? 'มากไปน้อย' : 'น้อยไปมาก'}
          </button>
        </div>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-sm text-left">
          <thead className="text-xs text-slate-300 uppercase bg-slate-950">
            <tr><th className="px-4 py-3">#</th><th className="px-4 py-3">ชื่อ</th><th className="px-4 py-3 text-center">มือ</th><th className="px-4 py-3 text-right">พลัง</th><th className="px-4 py-3 text-center">W/L (%)</th><th className="px-4 py-3 text-center">เข้าร่วม</th></tr>
          </thead>
          <tbody>
            {sorted.map((p, i) => {
              const winRate = Math.round((p.w / p.played) * 100) || 0;
              return (
                <tr key={p.id} className="border-b border-slate-700/30 hover:bg-slate-900/20">
                  <td className="px-4 py-3 font-bold text-slate-300">{i === 0 ? <Trophy className="w-4 h-4 text-amber-400" /> : i + 1}</td>
                  <td className="px-4 py-3 font-bold text-white flex items-center gap-2"><Avatar player={p} size="w-8 h-8" textSize="text-base" /> {p.name}</td>
                  <td className="px-4 py-3 text-center"><span className={`px-2 py-0.5 rounded text-xs font-bold border-2 ${clsColor(p.cls)}`}>{p.cls}</span></td>
                  <td className="px-4 py-3 text-right font-mono font-bold text-cyan-600">{p.power}</td>
                  <td className="px-4 py-3 text-center"><span className={winRate >= 50 ? 'text-cyan-600' : 'text-rose-400'}>{winRate}%</span><p className="text-[10px] text-cyan-500">{p.w}W - {p.l}L</p></td>
                  <td className="px-4 py-3 text-center font-mono text-slate-300">{attendanceCount(p.id)} วัน</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   ADMIN — live court board with real drag & drop
--------------------------------------------------------- */
/* ---------------------------------------------------------
   SLOT PICKER — manual player assignment for one court slot
--------------------------------------------------------- */
function SlotPickerModal({ waiting, currentPlayer, onSelect, onClear, onClose }) {
  return (
    <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-slate-900 border-2 border-slate-700/60 rounded-2xl max-w-sm w-full p-5 relative max-h-[80vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
        <button onClick={onClose} className="absolute top-4 right-4 text-slate-300 hover:text-white"><X className="w-5 h-5" /></button>
        <h3 className="text-sm font-bold text-white mb-3">เลือกผู้เล่นลงสนามนี้</h3>
        {currentPlayer && (
          <button onClick={onClear} className="w-full flex items-center justify-between px-3 py-2 rounded-lg text-sm border-2 border-rose-500/40 bg-rose-950/40 text-rose-400 mb-3">
            <span className="flex items-center gap-2"><Avatar player={currentPlayer} size="w-7 h-7" textSize="text-sm" /> {currentPlayer.name} <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded border-2 ${clsColor(currentPlayer.cls)}`}>มือ {currentPlayer.cls}</span> (คนปัจจุบัน)</span>
            <span className="text-xs font-bold">เอาออก</span>
          </button>
        )}
        <div className="space-y-1.5 max-h-96 overflow-y-auto pr-1">
          {waiting.length === 0 && <p className="text-sm text-slate-300 text-center py-6">ไม่มีคนรอลงเกม</p>}
          {waiting.map(p => (
            <button key={p.id} onClick={() => onSelect(p)}
              className="w-full flex items-center gap-2 px-3 py-2 rounded-lg text-sm border-2 border-slate-700/60 bg-slate-950 text-slate-200 hover:border-cyan-500/50 hover:bg-slate-900 transition-colors">
              <Avatar player={p} size="w-7 h-7" textSize="text-sm" /> {p.name}
              <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded border-2 ${clsColor(p.cls)}`}>มือ {p.cls}</span>
              <span className="ml-auto text-xs text-slate-300 font-mono">{p.power}</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

function AdminPage({ players, checkedInIds, courts, setCourts, onGameEnd, onOpenProfile, pairStats, togetherCounts, todayGroupStats, todayLukpatLowerGames, consecutiveCounts, restingIds, onToggleResting, paidMap }) {
  const [dragged, setDragged] = useState(null);
  const [pickerTarget, setPickerTarget] = useState(null); // { courtId, slotIndex } | null
  const [editingCourtNameId, setEditingCourtNameId] = useState(null);
  const [courtNameDraft, setCourtNameDraft] = useState('');

  const placedIds = new Set(courts.flatMap(c => c.players.filter(Boolean).map(p => p.id)));
  const waiting = players.filter(p => checkedInIds.includes(p.id) && !placedIds.has(p.id) && !paidMap[p.id]);
  const waitingForAI = waiting.filter(p => !restingIds.includes(p.id)); // AI Auto-Match ไม่จับคนที่กด "พักก่อน" ไว้

  const startDragFromWaiting = (player) => setDragged({ type: 'waiting', player });
  const startDragFromCourt = (courtId, slotIndex, player) => setDragged({ type: 'court', courtId, slotIndex, player });

  const startEditCourtName = (court) => { setEditingCourtNameId(court.id); setCourtNameDraft(court.name); };
  const saveCourtName = (id) => {
    setCourts(prev => prev.map(c => c.id === id ? { ...c, name: courtNameDraft.trim() || c.name } : c));
    setEditingCourtNameId(null);
  };

  // เพิ่มสนามใหม่ — ตั้งชื่ออัตโนมัติต่อจากเลขสนามที่มากที่สุดที่มีอยู่
  const addCourt = () => {
    setCourts(prev => {
      const nameNums = prev.map(c => parseInt((c.name.match(/\d+/) || ['0'])[0], 10)).filter(n => !isNaN(n));
      const nextNameNum = nameNums.length ? Math.max(...nameNums) + 1 : prev.length + 1;
      const idNums = prev.map(c => parseInt((c.id.match(/\d+/) || ['0'])[0], 10)).filter(n => !isNaN(n));
      const nextIdNum = idNums.length ? Math.max(...idNums) + 1 : prev.length + 1;
      return [...prev, {
        id: `c${nextIdNum}`, name: `สนาม ${nextNameNum}`, status: 'waiting',
        players: [null, null, null, null], shuttlecocks: 1, matchType: 'open', difficulty: 'all',
      }];
    });
  };

  // ลบสนามออก — ห้ามลบสนามที่กำลังเล่นอยู่ (ต้องจบเกมก่อน) และห้ามเหลือน้อยกว่า 1 สนาม
  const removeCourt = (id) => {
    setCourts(prev => {
      const court = prev.find(c => c.id === id);
      if (!court || court.status === 'playing' || prev.length <= 1) return prev;
      return prev.filter(c => c.id !== id);
    });
  };

  const recomputeStatus = (court) => court.status === 'playing' ? court : { ...court, status: court.players.every(Boolean) ? 'ready' : 'waiting' };

  const dropOnCourtSlot = (courtId, slotIndex) => {
    if (!dragged) return;
    setCourts(prev => {
      const next = prev.map(c => ({ ...c, players: [...c.players] }));
      const target = next.find(c => c.id === courtId);
      if (target.status === 'playing') return prev;
      const existing = target.players[slotIndex];
      if (dragged.type === 'waiting') {
        target.players[slotIndex] = dragged.player;
      } else {
        const source = next.find(c => c.id === dragged.courtId);
        if (source.status === 'playing') return prev;
        source.players[dragged.slotIndex] = existing || null;
        target.players[slotIndex] = dragged.player;
      }
      return next.map(recomputeStatus);
    });
    setDragged(null);
  };

  const dropOnWaiting = () => {
    if (!dragged || dragged.type !== 'court') { setDragged(null); return; }
    setCourts(prev => {
      const next = prev.map(c => ({ ...c, players: [...c.players] }));
      const source = next.find(c => c.id === dragged.courtId);
      if (source.status === 'playing') return prev;
      source.players[dragged.slotIndex] = null;
      return next.map(recomputeStatus);
    });
    setDragged(null);
  };

  const autoMatch = (courtId) => {
    const court = courts.find(c => c.id === courtId);
    const matchType = court?.matchType || 'open';
    const difficulty = court?.difficulty || 'all';
    const filledCount = court.players.filter(Boolean).length;

    let slots;
    if (filledCount > 0) {
      // มีคนวางไว้เองบางช่องแล้ว — เติมเฉพาะช่องที่เหลือจากคิวรอ (ไม่รวมคนพัก) คงคนที่วางไว้แล้วไว้ตามเดิม
      slots = fillRemainingSlots(court, waitingForAI, matchType, difficulty, togetherCounts, todayGroupStats, todayLukpatLowerGames, consecutiveCounts, pairStats);
      if (!slots) return;
    } else {
      const quartet = pickQuartetByType(waitingForAI, matchType, difficulty, togetherCounts, todayGroupStats, todayLukpatLowerGames, consecutiveCounts);
      if (!quartet) return;
      slots = quartetToSlots(quartet, pairStats, matchType, togetherCounts);
    }
    setCourts(prev => prev.map(c => c.id === courtId ? { ...c, players: slots, status: 'ready' } : c));
  };

  const setMatchType = (courtId, matchType) => setCourts(prev => prev.map(c => c.id === courtId ? { ...c, matchType } : c));
  const setDifficulty = (courtId, difficulty) => setCourts(prev => prev.map(c => c.id === courtId ? { ...c, difficulty } : c));

  const canAutoMatch = (matchType, difficulty = 'all', filledCount = 0) => {
    const needed = 4 - filledCount;
    if (needed <= 0) return false;
    if (difficulty === 'cross') {
      let pool = waitingForAI;
      if (matchType === 'men') pool = pool.filter(p => p.gender === 'M');
      if (matchType === 'women') pool = pool.filter(p => p.gender === 'F');
      const lowMaxIdx = TIERS.indexOf('NB');
      const highMinIdx = TIERS.indexOf('N');
      const lowCount = pool.filter(p => TIERS.indexOf(p.cls) <= lowMaxIdx).length;
      const highCount = pool.filter(p => TIERS.indexOf(p.cls) >= highMinIdx).length;
      // ต้องมีอย่างน้อยฝั่งละ 1 (ถ้าเติมแค่ 1-2 ช่อง อาจไม่ต้องครบ 2-2 เป๊ะ) แต่ถ้าเติมทั้ง 4 ช่องต้องได้ฝั่งละ 2
      if (filledCount === 0) return lowCount >= 2 && highCount >= 2;
      return (lowCount + highCount) >= needed;
    }
    const pool = filterByDifficulty(waitingForAI, difficulty);
    const menCount = pool.filter(p => p.gender === 'M').length;
    const womenCount = pool.filter(p => p.gender === 'F').length;
    if (filledCount > 0) return pool.length >= needed; // เติมช่องที่เหลือ ไม่บังคับสัดส่วนเพศเป๊ะเหมือนจัดใหม่ทั้งหมด
    if (matchType === 'men') return menCount >= 4;
    if (matchType === 'women') return womenCount >= 4;
    if (matchType === 'mixed') return menCount >= 2 && womenCount >= 2;
    return pool.length >= 4;
  };

  const startGame = (courtId) => setCourts(prev => prev.map(c => c.id === courtId ? { ...c, status: 'playing' } : c));

  const endGame = (courtId, winner) => {
    const court = courts.find(c => c.id === courtId);
    onGameEnd(court, winner);
    setCourts(prev => prev.map(c => c.id === courtId ? { ...c, status: 'waiting', players: [null, null, null, null], shuttlecocks: 1 } : c));
  };

  const addShuttle = (courtId) => setCourts(prev => prev.map(c => c.id === courtId ? { ...c, shuttlecocks: c.shuttlecocks + 1 } : c));
  const removeShuttle = (courtId) => setCourts(prev => prev.map(c => c.id === courtId ? { ...c, shuttlecocks: Math.max(0, c.shuttlecocks - 1) } : c));

  const assignSlotManually = (player) => {
    if (!pickerTarget) return;
    setCourts(prev => {
      const next = prev.map(c => ({ ...c, players: [...c.players] }));
      const target = next.find(c => c.id === pickerTarget.courtId);
      target.players[pickerTarget.slotIndex] = player;
      return next.map(recomputeStatus);
    });
    setPickerTarget(null);
  };

  const clearSlotManually = () => {
    if (!pickerTarget) return;
    setCourts(prev => {
      const next = prev.map(c => ({ ...c, players: [...c.players] }));
      const target = next.find(c => c.id === pickerTarget.courtId);
      target.players[pickerTarget.slotIndex] = null;
      return next.map(recomputeStatus);
    });
    setPickerTarget(null);
  };

  const pickerCurrentPlayer = pickerTarget
    ? courts.find(c => c.id === pickerTarget.courtId)?.players[pickerTarget.slotIndex] || null
    : null;

  return (
    <>
    <div className="space-y-6">
      <div className="space-y-4">
        <div className="flex justify-end">
          <button onClick={addCourt} className="bg-cyan-600 hover:bg-cyan-500 text-white text-sm font-bold px-3.5 py-2.5 rounded-lg flex items-center gap-1.5">
            <Plus className="w-4 h-4" /> เพิ่มสนาม
          </button>
        </div>
        {courts.map(court => (
          <div key={court.id} className={`bg-slate-900 border-2 rounded-2xl p-4 transition-all ${court.status === 'playing' ? 'border-emerald-500/40 shadow-[0_0_15px_rgba(16,185,129,0.1)]' : 'border-slate-700/60'}`}>
            <div className="flex flex-wrap justify-between items-center mb-4 gap-3">
              <div className="flex items-center gap-3">
                {editingCourtNameId === court.id ? (
                  <input
                    autoFocus
                    value={courtNameDraft}
                    onChange={(e) => setCourtNameDraft(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && saveCourtName(court.id)}
                    onBlur={() => saveCourtName(court.id)}
                    className="text-lg font-black text-white bg-slate-950 border-2 border-cyan-500 rounded-lg px-2 py-0.5 w-32 focus:outline-none"
                  />
                ) : (
                  <button onClick={() => startEditCourtName(court)} className="flex items-center gap-1.5 group" title="แก้ไขชื่อสนาม">
                    <h3 className="text-lg font-black text-white">{court.name}</h3>
                    <Pencil className="w-3.5 h-3.5 text-slate-600 group-hover:text-cyan-500" />
                  </button>
                )}
                {court.status === 'playing' && <span className="flex items-center gap-1 text-xs font-bold text-emerald-400 bg-emerald-950/40 px-2 py-1 rounded border-2 border-emerald-600"><Play className="w-3 h-3" /> กำลังประลอง</span>}
                {court.status === 'waiting' && <span className="text-xs font-bold text-slate-300 bg-slate-950/50 px-2 py-1 rounded">รอผู้เล่น</span>}
                {court.status === 'ready' && <span className="text-xs font-bold text-cyan-400 bg-cyan-950/40 px-2 py-1 rounded">พร้อมเริ่ม</span>}
                {court.status !== 'playing' && courts.length > 1 && (
                  <button onClick={() => removeCourt(court.id)} title="ลบสนามนี้" className="text-slate-600 hover:text-rose-400">
                    <Trash2 className="w-4 h-4" />
                  </button>
                )}
              </div>
              <div className="flex items-center gap-2">
                <div className="flex items-center gap-1.5 bg-slate-950 px-3 py-1.5 rounded-lg border-2 border-slate-700/50">
                  <span className="text-xs text-slate-300 mr-1">ลูกแบด:</span>
                  <button onClick={() => removeShuttle(court.id)} disabled={court.shuttlecocks === 0}
                    className="w-5 h-5 flex items-center justify-center rounded text-slate-300 hover:text-rose-400 hover:bg-rose-500/10 disabled:opacity-30 disabled:hover:bg-transparent">
                    <Minus className="w-3.5 h-3.5" />
                  </button>
                  <span className="font-mono font-bold text-cyan-600 w-4 text-center">{court.shuttlecocks}</span>
                  <button onClick={() => addShuttle(court.id)} className="w-5 h-5 flex items-center justify-center rounded text-slate-300 hover:text-cyan-600 hover:bg-cyan-500/10">
                    <Plus className="w-3.5 h-3.5" />
                  </button>
                </div>
                {court.status === 'waiting' ? (
                  <>
                    <select
                      value={court.difficulty || 'all'}
                      onChange={(e) => setDifficulty(court.id, e.target.value)}
                      className="bg-slate-950 border-2 border-slate-700/60 rounded-lg px-3 py-2.5 text-sm text-slate-200 focus:outline-none focus:border-cyan-500"
                    >
                      <option value="all">ทุกระดับ</option>
                      <option value="light">เกมเบา (BG1-NB)</option>
                      <option value="medium">เกมกลาง (NB ขึ้นไป)</option>
                      <option value="heavy">เกมหนัก (N ขึ้นไป)</option>
                      <option value="cross">เกมผสม (มือต่ำพบมือสูง)</option>
                    </select>
                    <select
                      value={court.matchType}
                      onChange={(e) => setMatchType(court.id, e.target.value)}
                      className="bg-slate-950 border-2 border-slate-700/60 rounded-lg px-3 py-2.5 text-sm text-slate-200 focus:outline-none focus:border-cyan-500"
                    >
                      <option value="open">ทั่วไป</option>
                      <option value="men">ชายคู่</option>
                      <option value="women">หญิงคู่</option>
                      <option value="mixed">คู่ผสม</option>
                    </select>
                    <button onClick={() => autoMatch(court.id)} disabled={!canAutoMatch(court.matchType, court.difficulty || 'all', court.players.filter(Boolean).length)}
                      className="bg-cyan-600 hover:bg-cyan-500 disabled:bg-slate-950 disabled:text-slate-300 text-white text-sm font-bold px-3.5 py-2.5 rounded-lg flex items-center gap-1.5">
                      <Zap className="w-4 h-4" /> AI Auto-Match
                    </button>
                  </>
                ) : court.status === 'ready' ? (
                  <button onClick={() => startGame(court.id)} className="bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold px-4 py-2 rounded-lg flex items-center gap-1">
                    <Play className="w-4 h-4 fill-current" /> เริ่มเกม
                  </button>
                ) : (
                  <div className="flex items-center gap-1.5 flex-wrap">
                    <span className="text-[10px] text-slate-300 hidden sm:inline">ผลเกม?</span>
                    <button onClick={() => endGame(court.id, 'A')} className={`${TEAM.A.bg} hover:${TEAM.A.solid} text-red-400 hover:text-white border-2 ${TEAM.A.border} text-sm font-bold px-3.5 py-2.5 rounded-lg flex items-center gap-1.5`}>
                      <Trophy className="w-3.5 h-3.5" /> {TEAM.A.name}
                    </button>
                    <button onClick={() => endGame(court.id, 'B')} className={`${TEAM.B.bg} hover:${TEAM.B.solid} text-blue-400 hover:text-white border-2 ${TEAM.B.border} text-sm font-bold px-3.5 py-2.5 rounded-lg flex items-center gap-1.5`}>
                      <Trophy className="w-3.5 h-3.5" /> {TEAM.B.name}
                    </button>
                    <button onClick={() => endGame(court.id, 'draw')} className="bg-slate-950 hover:bg-amber-600 text-amber-400 hover:text-white border-2 border-amber-500/50 text-sm font-bold px-3.5 py-2.5 rounded-lg flex items-center gap-1.5">
                      <Minus className="w-3.5 h-3.5" /> เสมอ
                    </button>
                  </div>
                )}
              </div>
            </div>
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
              {court.players.map((p, index) => {
                const team = index < 2 ? TEAM.A : TEAM.B;
                const editable = court.status !== 'playing';
                return (
                  <div key={index}
                    onDragOver={(e) => e.preventDefault()}
                    onDrop={() => dropOnCourtSlot(court.id, index)}
                    onClick={() => { if (editable && !p) setPickerTarget({ courtId: court.id, slotIndex: index }); }}
                    className={`min-h-[6.5rem] rounded-xl border-2 flex items-center relative px-3 py-2 transition-all ${p ? `${team.border} ${team.bg} border-solid` : 'border-dashed border-slate-700/30 hover:border-cyan-500/50 bg-slate-950/10 justify-center'} ${editable && !p ? 'cursor-pointer' : ''}`}>
                    {p ? (
                      <div draggable={court.status !== 'playing'} onDragStart={() => startDragFromCourt(court.id, index, p)} className="flex items-center gap-3 w-full cursor-grab active:cursor-grabbing">
                        <GripHorizontal className="w-3 h-3 text-slate-300 absolute top-1 right-1" />
                        <Avatar player={p} size="w-16 h-16" textSize="text-3xl" ring="" />
                        <div className="flex flex-col min-w-0 flex-1">
                          <div className="flex items-center gap-1.5 flex-wrap">
                            <span className="text-base font-bold text-white truncate max-w-[110px]">{p.name}</span>
                            <span className={`text-base font-bold ${p.gender === 'F' ? 'text-pink-400' : 'text-blue-400'}`}>{p.gender === 'F' ? '♀' : '♂'}</span>
                            {p.isVeteran && <span className="text-xs opacity-70">🪫</span>}
                          </div>
                          <span className={`text-xs font-bold px-1.5 py-0.5 rounded mt-1 border-2 w-fit ${clsColor(p.cls)}`}>มือ {p.cls}</span>
                        </div>
                      </div>
                    ) : <span className="text-xs text-slate-300 font-medium">+ วางผู้เล่น</span>}
                    {editable && (
                      <button
                        onClick={(e) => { e.stopPropagation(); setPickerTarget({ courtId: court.id, slotIndex: index }); }}
                        className="absolute bottom-1.5 right-1.5 w-9 h-9 rounded-full bg-slate-900 border-2 border-slate-700 flex items-center justify-center text-slate-300 hover:text-cyan-600 hover:border-cyan-500/50"
                        title="เลือกผู้เล่นเอง"
                      >
                        <Pencil className="w-3.5 h-3.5" />
                      </button>
                    )}
                  </div>
                );
              })}
            </div>
            <div className="flex items-center gap-4 mt-2 text-[10px] font-bold">
              <span className={TEAM.A.text}>■ {TEAM.A.name}</span>
              <span className={TEAM.B.text}>■ {TEAM.B.name}</span>
            </div>
          </div>
        ))}
      </div>

      <div
        className="bg-slate-900 border-2 border-slate-700/60 rounded-2xl p-4"
        onDragOver={(e) => e.preventDefault()}
        onDrop={dropOnWaiting}
      >
        <div className="flex items-center justify-between mb-4 border-b border-slate-700/50 pb-2">
          <h2 className="font-bold text-white flex items-center gap-2"><Users className="w-5 h-5 text-cyan-600" /> รอลงเกม</h2>
          <span className="bg-cyan-950/40 text-cyan-400 px-2 py-0.5 rounded text-sm font-bold border-2 border-cyan-500">{waiting.length} คน</span>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
          {waiting.map(p => {
            const isResting = restingIds.includes(p.id);
            return (
              <div key={p.id} draggable onDragStart={() => startDragFromWaiting(p)}
                className={`border-2 p-3 rounded-xl flex items-center gap-3 cursor-grab active:cursor-grabbing group transition-all ${isResting ? 'bg-slate-950/50 border-amber-600 opacity-60' : 'bg-slate-950 border-slate-700/50 hover:border-cyan-500/50'}`}>
                <Avatar player={p} size="w-14 h-14" textSize="text-2xl" />
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-1.5 flex-wrap">
                    <p className="font-bold text-base text-white group-hover:text-cyan-400 truncate max-w-[130px]">{p.name}</p>
                    <span className={`text-base font-bold ${p.gender === 'F' ? 'text-pink-400' : 'text-blue-400'}`}>{p.gender === 'F' ? '♀' : '♂'}</span>
                    {p.isVeteran && <span className="text-xs shrink-0" title="สายเทคนิค/ลดความเร็ว">🪫</span>}
                  </div>
                  <div className="flex items-center gap-1.5 mt-1">
                    <span className={`text-xs font-bold px-1.5 py-0.5 rounded border-2 ${clsColor(p.cls)}`}>มือ {p.cls}</span>
                    {isResting && <span className="text-xs font-bold px-1.5 py-0.5 rounded border-2 border-amber-600/50 text-amber-400">พัก</span>}
                  </div>
                </div>
                <div className="flex flex-col items-center gap-2 shrink-0">
                  <button onClick={() => onOpenProfile(p.id)} className="text-cyan-500 hover:text-cyan-400"><Info className="w-6 h-6" /></button>
                  <button
                    onClick={() => onToggleResting(p.id)}
                    title={isResting ? 'พร้อมเล่น' : 'พักก่อน'}
                    className={isResting ? 'text-emerald-400 hover:text-emerald-400' : 'text-amber-500 hover:text-amber-400'}
                  >
                    {isResting ? <Play className="w-6 h-6" /> : <PauseCircle className="w-6 h-6" />}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
        {waiting.length === 0 && (
          <div className="flex flex-col items-center gap-2 py-8 text-cyan-600 text-sm border-2 border-dashed border-slate-700/40 rounded-xl px-3">
            <img src={MASCOT_SHUTTLE} alt="" className="w-14 h-14 object-contain opacity-80" />
            {checkedInIds.length === 0 ? 'ยังไม่มีใครเช็คอิน — ไปเช็คอินที่หน้าแรกก่อนนะคะ' : 'ทุกคนลงคอร์ทหรือจ่ายเงินเสร็จแล้ว'}
          </div>
        )}
      </div>
    </div>
    {pickerTarget && (
      <SlotPickerModal
        waiting={waiting}
        currentPlayer={pickerCurrentPlayer}
        onSelect={assignSlotManually}
        onClear={clearSlotManually}
        onClose={() => setPickerTarget(null)}
      />
    )}
    </>
  );
}

/* ---------------------------------------------------------
   FINANCE — auto-tallied per match, with editable pricing
--------------------------------------------------------- */
function FinancePage({ players, matchRecords, paidMap, onMarkPaid, onUnmarkPaid, dailyPrices, onChangeTodayPrice }) {
  const [payPromptId, setPayPromptId] = useState(null);
  const todayKey = dayKeyOf(Date.now());
  const todayPrice = priceForDay(dailyPrices, todayKey);
  const duesRaw = computeDues(matchRecords, dailyPrices);
  const dues = duesRaw.map(d => ({ ...d, player: players.find(p => p.id === d.id) })).filter(d => d.player);
  const totalExpected = dues.reduce((s, d) => s + d.total, 0);
  const collected = dues.filter(d => paidMap[d.player.id]).reduce((s, d) => s + d.total, 0);
  const totalShuttles = matchRecords.reduce((s, r) => s + r.shuttlecocks, 0);

  const handleMarkPaid = (id, method) => {
    onMarkPaid(id, method);
    setPayPromptId(null);
  };

  return (
    <div className="space-y-6">
      <div className="bg-slate-900 border-2 border-slate-700/60 rounded-2xl p-6 relative overflow-hidden">
        <div className="absolute left-0 bottom-0 w-1 h-full bg-gradient-to-b from-cyan-600 to-cyan-500" />
        <h2 className="text-xl font-black text-white mb-1">สรุปค่าใช้จ่ายวันนี้</h2>
        <p className="text-slate-300 text-sm mb-4">ผู้เล่นแต่ละคนจ่ายค่าสนามแค่ครั้งเดียวต่อวัน (เกมแรกที่ลง) ส่วนค่าลูกคิดเต็มตามทุกเกมที่เล่นจริง ไม่หารเฉลี่ย</p>

        <div className="bg-slate-950 rounded-xl p-3 border-2 border-slate-700/50 mb-4">
          <p className="text-xs text-slate-300 mb-2 flex items-center gap-1"><Settings className="w-3.5 h-3.5" /> ตั้งราคาของวันนี้ (คำนวณย้อนหลังทุกเกมของวันนี้ทันที ไม่กระทบวันก่อนหน้า)</p>
          <div className="grid grid-cols-2 gap-3">
            <label className="text-xs text-slate-300">
              ค่าคอร์ท/เกม (บาท)
              <input type="number" min="0" value={todayPrice.courtFee} onChange={(e) => onChangeTodayPrice({ courtFee: Number(e.target.value) || 0, shuttlePrice: todayPrice.shuttlePrice })}
                className="mt-1 w-full bg-slate-900 border-2 border-slate-700/60 rounded-lg px-2 py-1.5 text-sm text-white focus:outline-none focus:border-cyan-500" />
            </label>
            <label className="text-xs text-slate-300">
              ค่าลูกแบด/ลูก (บาท)
              <input type="number" min="0" value={todayPrice.shuttlePrice} onChange={(e) => onChangeTodayPrice({ courtFee: todayPrice.courtFee, shuttlePrice: Number(e.target.value) || 0 })}
                className="mt-1 w-full bg-slate-900 border-2 border-slate-700/60 rounded-lg px-2 py-1.5 text-sm text-white focus:outline-none focus:border-cyan-500" />
            </label>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-3 mb-4 text-sm">
          <div className="bg-slate-950 rounded-lg p-3 border-2 border-slate-700/50 flex justify-between"><span className="text-slate-300">เกมที่เล่นจบ</span><span className="font-mono text-white">{matchRecords.length} เกม</span></div>
          <div className="bg-slate-950 rounded-lg p-3 border-2 border-slate-700/50 flex justify-between"><span className="text-slate-300">ลูกแบดรวม</span><span className="font-mono text-white">{totalShuttles} ลูก</span></div>
        </div>
        <div className="flex items-end gap-2">
          <span className="text-3xl font-black text-cyan-600 font-mono">฿{collected}</span>
          <span className="text-slate-300 mb-1">/ ฿{totalExpected}</span>
        </div>
        <div className="w-full h-2 bg-slate-950 rounded-full overflow-hidden border-2 border-slate-700/50 mt-2">
          <div className="h-full bg-gradient-to-r from-cyan-600 to-blue-500" style={{ width: totalExpected ? `${(collected / totalExpected) * 100}%` : '0%' }} />
        </div>
      </div>
      <div className="space-y-3">
        {dues.length === 0 && <p className="text-sm text-cyan-500 text-center py-6">ยังไม่มีใครลงเล่นวันนี้ — ไปจัดคู่ในหน้าแอดมินก่อนนะคะ</p>}
        {dues.map(d => {
          const paidInfo = paidMap[d.player.id];
          const isPrompting = payPromptId === d.player.id;
          return (
            <div key={d.player.id} className={`p-3 rounded-xl border-2 ${paidInfo ? 'bg-slate-900 border-emerald-600' : 'bg-slate-900 border-rose-600'}`}>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <Avatar player={d.player} size="w-10 h-10" textSize="text-xl" ring="border-2 border-slate-700/60" />
                  <div>
                    <p className="font-bold text-white text-sm">{d.player.name}</p>
                    <p className="text-xs text-cyan-500 font-mono">{d.games} เกม · (฿{d.courtFeePaid} ค่าสนาม + ฿{d.shuttleCost} ค่าลูก {d.shuttles} ลูก) = ฿{d.total}</p>
                  </div>
                </div>
                {paidInfo ? (
                  <button onClick={() => onUnmarkPaid(d.player.id)} className="px-3 py-1.5 rounded-lg text-xs font-bold border-2 flex items-center gap-1 bg-emerald-500/10 border-emerald-500/30 text-emerald-400">
                    <CheckCircle2 className="w-4 h-4" /> จ่ายแล้ว ({paidInfo.method === 'cash' ? 'เงินสด' : 'เงินโอน'})
                  </button>
                ) : (
                  <button onClick={() => setPayPromptId(isPrompting ? null : d.player.id)} className="px-3 py-1.5 rounded-lg text-xs font-bold border-2 flex items-center gap-1 bg-rose-500/10 border-rose-500/30 text-rose-400">
                    <AlertCircle className="w-4 h-4" /> รอชำระ
                  </button>
                )}
              </div>
              {isPrompting && !paidInfo && (
                <div className="mt-3 pt-3 border-t border-slate-700/50 flex items-center gap-2">
                  <span className="text-xs text-slate-300">จ่ายด้วย:</span>
                  <button onClick={() => handleMarkPaid(d.player.id, 'cash')} className="flex-1 py-2 rounded-lg text-xs font-bold border-2 border-emerald-500/40 bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500/20 flex items-center justify-center gap-1">
                    <Wallet className="w-3.5 h-3.5" /> เงินสด
                  </button>
                  <button onClick={() => handleMarkPaid(d.player.id, 'transfer')} className="flex-1 py-2 rounded-lg text-xs font-bold border-2 border-cyan-500/40 bg-cyan-500/10 text-cyan-400 hover:bg-cyan-500/20 flex items-center justify-center gap-1">
                    <RefreshCw className="w-3.5 h-3.5" /> เงินโอน
                  </button>
                  <button onClick={() => setPayPromptId(null)} className="text-slate-300 hover:text-slate-300"><X className="w-4 h-4" /></button>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   APP SHELL
--------------------------------------------------------- */
export default function IbabadApp() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [appPassword, setAppPassword] = useState(DEFAULT_PASSWORD);
  const [players, setPlayers] = useState(initialPlayers);
  const [tab, setTab] = useState('home');
  const [profileId, setProfileId] = useState(null);

  const [courts, setCourts] = useState([
    { id: 'c1', name: 'สนาม 1', status: 'waiting', players: [null, null, null, null], shuttlecocks: 1, matchType: 'open', difficulty: 'all' },
    { id: 'c2', name: 'สนาม 2', status: 'waiting', players: [null, null, null, null], shuttlecocks: 1, matchType: 'open', difficulty: 'all' },
    { id: 'c3', name: 'สนาม 3', status: 'waiting', players: [null, null, null, null], shuttlecocks: 1, matchType: 'open', difficulty: 'all' },
  ]);

  const [matchRecords, setMatchRecords] = useState([]);
  const [paidMap, setPaidMap] = useState({});
  const [checkedInIds, setCheckedInIds] = useState([]);
  const [restingIds, setRestingIds] = useState([]);
  const [attendance, setAttendance] = useState({}); // { [playerId]: { [dayKey]: true } } — นับเข้าร่วมสูงสุด 1 แต้ม/วัน
  const [dailyPrices, setDailyPrices] = useState({}); // { [dayKey]: { courtFee, shuttlePrice } } — ราคาล็อกตามวัน แก้วันนี้ไม่กระทบวันก่อนหน้า

  const [isSynced, setIsSynced] = useState(false); // โหลดข้อมูลจาก Supabase รอบแรกเสร็จหรือยัง
  const [syncError, setSyncError] = useState(null);
  const isApplyingRemote = useRef(false);   // true ระหว่างที่กำลังเอาข้อมูลจากเซิร์ฟเวอร์มาใส่ state (กันไม่ให้เขียนวนกลับไป)
  const lastLocalWriteAt = useRef(0);       // เวลาที่เครื่องนี้เขียนขึ้นเซิร์ฟเวอร์ล่าสุด (กันโพลทับข้อมูลสดๆ ของตัวเอง)
  const lastKnownUpdatedAt = useRef(null);  // updated_at ล่าสุดที่เครื่องนี้รู้ (เทียบว่าของเซิร์ฟเวอร์ใหม่กว่าไหม)
  const saveTimer = useRef(null);

  const collectStateForSync = () => ({
    appPassword, players, courts, matchRecords, paidMap,
    checkedInIds, restingIds, attendance, dailyPrices,
  });

  const applyRemoteState = (data) => {
    isApplyingRemote.current = true;
    if (data.appPassword !== undefined) setAppPassword(data.appPassword);
    if (data.players !== undefined) setPlayers(data.players);
    if (data.courts !== undefined) setCourts(data.courts);
    if (data.matchRecords !== undefined) setMatchRecords(data.matchRecords);
    if (data.paidMap !== undefined) setPaidMap(data.paidMap);
    if (data.checkedInIds !== undefined) setCheckedInIds(data.checkedInIds);
    if (data.restingIds !== undefined) setRestingIds(data.restingIds);
    if (data.attendance !== undefined) setAttendance(data.attendance);
    if (data.dailyPrices !== undefined) setDailyPrices(data.dailyPrices);
  };

  // โหลดข้อมูลจาก Supabase ตอนเปิดแอปครั้งแรก (ถ้ายังไม่เคยมีแถวข้อมูลเลย จะสร้างแถวเริ่มต้นให้)
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const { data, error } = await supabase
        .from('app_state')
        .select('data, updated_at')
        .eq('id', APP_STATE_ROW_ID)
        .maybeSingle();
      if (cancelled) return;
      if (error) {
        setSyncError('เชื่อมต่อฐานข้อมูลไม่ได้ — ตรวจสอบการตั้งค่า Supabase (ดู src/supabaseClient.js)');
        setIsSynced(true);
        return;
      }
      if (data) {
        applyRemoteState(data.data || {});
        lastKnownUpdatedAt.current = data.updated_at;
      } else {
        // ยังไม่เคยมีแถวข้อมูล — สร้างแถวแรกด้วยค่าเริ่มต้นของแอป
        const initial = { appPassword: DEFAULT_PASSWORD, players: initialPlayers, courts: [
          { id: 'c1', name: 'สนาม 1', status: 'waiting', players: [null, null, null, null], shuttlecocks: 1, matchType: 'open', difficulty: 'all' },
          { id: 'c2', name: 'สนาม 2', status: 'waiting', players: [null, null, null, null], shuttlecocks: 1, matchType: 'open', difficulty: 'all' },
          { id: 'c3', name: 'สนาม 3', status: 'waiting', players: [null, null, null, null], shuttlecocks: 1, matchType: 'open', difficulty: 'all' },
        ], matchRecords: [], paidMap: {}, checkedInIds: [], restingIds: [], attendance: {}, dailyPrices: {} };
        const { data: inserted } = await supabase
          .from('app_state')
          .insert({ id: APP_STATE_ROW_ID, data: initial, updated_at: new Date().toISOString() })
          .select('data, updated_at')
          .single();
        if (inserted) lastKnownUpdatedAt.current = inserted.updated_at;
      }
      setIsSynced(true);
    })();
    return () => { cancelled = true; };
  }, []);

  // โพลข้อมูลใหม่จากเซิร์ฟเวอร์เป็นระยะ เพื่อรับการเปลี่ยนแปลงจากอุปกรณ์เครื่องอื่น
  useEffect(() => {
    if (!isSynced) return;
    const interval = setInterval(async () => {
      const { data, error } = await supabase
        .from('app_state')
        .select('data, updated_at')
        .eq('id', APP_STATE_ROW_ID)
        .maybeSingle();
      if (error || !data) return;
      const isNewer = data.updated_at !== lastKnownUpdatedAt.current;
      const recentlyWroteOurselves = Date.now() - lastLocalWriteAt.current < RECENT_LOCAL_WRITE_GUARD_MS;
      if (isNewer && !recentlyWroteOurselves) {
        applyRemoteState(data.data || {});
        lastKnownUpdatedAt.current = data.updated_at;
      }
    }, POLL_INTERVAL_MS);
    return () => clearInterval(interval);
  }, [isSynced]);

  // บันทึกขึ้น Supabase (หน่วงเวลาเล็กน้อยเพื่อไม่ยิงถี่เกินไป) ทุกครั้งที่ข้อมูลในเครื่องนี้เปลี่ยน
  useEffect(() => {
    if (!isSynced) return; // ยังโหลดรอบแรกไม่เสร็จ อย่าเพิ่งเขียนทับด้วยค่า default
    if (isApplyingRemote.current) { isApplyingRemote.current = false; return; } // การเปลี่ยนแปลงรอบนี้มาจากรีโมต ไม่ต้องเขียนกลับ

    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(async () => {
      const nowIso = new Date().toISOString();
      const { data, error } = await supabase
        .from('app_state')
        .update({ data: collectStateForSync(), updated_at: nowIso })
        .eq('id', APP_STATE_ROW_ID)
        .select('updated_at')
        .single();
      if (!error && data) {
        lastKnownUpdatedAt.current = data.updated_at;
        lastLocalWriteAt.current = Date.now();
        setSyncError(null);
      } else if (error) {
        setSyncError('บันทึกขึ้นฐานข้อมูลไม่สำเร็จ — การเปลี่ยนแปลงล่าสุดอาจยังไม่ถูกบันทึก');
      }
    }, SAVE_DEBOUNCE_MS);
    return () => { if (saveTimer.current) clearTimeout(saveTimer.current); };
  }, [appPassword, players, courts, matchRecords, paidMap, checkedInIds, restingIds, attendance, dailyPrices, isSynced]);

  // เช็คอิน (เปิด) แล้วได้แต้มเข้าร่วมของวันนี้ ถ้ายังไม่เคยได้วันนี้ — เช็คเอาต์ไม่ลบแต้มที่ได้ไปแล้ว
  const toggleCheckIn = (id) => {
    const isIn = checkedInIds.includes(id);
    const today = dayKeyOf(Date.now());
    if (!isIn) {
      // เช็คอิน: นับแต้มเข้าร่วมของวันนี้ ถ้ายังไม่เคยได้วันนี้
      setAttendance(prev => {
        const existing = prev[id] || {};
        if (existing[today]) return prev;
        return { ...prev, [id]: { ...existing, [today]: true } };
      });
    } else {
      // เอาชื่อออก (เช็คเอาต์): ถ้ายังไม่เคยลงเล่นเกมไหนเลยวันนี้ ให้ถือว่าเป็นการเช็คอินผิดพลาด
      // ถอนแต้มเข้าร่วมของวันนี้คืน เพื่อไม่ให้นับว่ามาแล้ว 1 วันทั้งที่จริงไม่ได้มาเล่น
      const playedToday = matchRecords.some(r => dayKeyOf(r.timestamp) === today && r.playerIds.includes(id));
      if (!playedToday) {
        setAttendance(prev => {
          const existing = prev[id];
          if (!existing || !existing[today]) return prev;
          const rest = { ...existing };
          delete rest[today];
          return { ...prev, [id]: rest };
        });
      }
    }
    setCheckedInIds(prev => isIn ? prev.filter(x => x !== id) : [...prev, id]);
  };
  const toggleResting = (id) => setRestingIds(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);

  // แก้ราคาของ "วันนี้" เท่านั้น — คำนวณย้อนหลังทุกเกมที่จบไปแล้ววันนี้ทันที แต่ไม่กระทบวันก่อนหน้าที่ล็อกราคาของตัวเองไว้แล้ว
  const changeTodayPrice = (newPrice) => {
    const today = dayKeyOf(Date.now());
    setDailyPrices(prev => ({ ...prev, [today]: newPrice }));
  };

  const handleGameEnd = (court, winner) => {
    const teamA = court.players.slice(0, 2).filter(Boolean).map(p => p.id);
    const teamB = court.players.slice(2, 4).filter(Boolean).map(p => p.id);
    // คำนวณ Elo delta ไว้ล่วงหน้าด้วยพลังปัจจุบัน (ก่อน setPlayers) เพื่อแนบไว้กับประวัติแมทช์ ให้หน้าประวัติย้อนหลังโชว์ได้แม่นยำ
    const { deltaA, deltaB } = computeEloDeltas(players, teamA, teamB, winner);
    const powerDeltas = {};
    teamA.forEach(id => { powerDeltas[id] = deltaA; });
    teamB.forEach(id => { powerDeltas[id] = deltaB; });
    setMatchRecords(prev => [...prev, {
      id: `${court.id}-${Date.now()}`,
      courtId: court.id,
      courtName: court.name,
      teamA, teamB,
      playerIds: [...teamA, ...teamB],
      shuttlecocks: court.shuttlecocks,
      winner,
      timestamp: Date.now(),
      powerDeltas,
    }]);
    setPlayers(prev => updateEloForMatch(prev, teamA, teamB, winner));
  };

  // แก้ไขผลแพ้/ชนะ/เสมอของเกมที่จบไปแล้วในหน้าประวัติ — ปรับพลัง (power) ของผู้เล่นในเกมนั้นให้ตรงกับผลใหม่
  // หมายเหตุ: คำนวณ delta ใหม่จากพลังปัจจุบันของผู้เล่น (ไม่ได้จำลองย้อนหลังทั้งสายเกมหลังจากนั้นใหม่ทั้งหมด)
  // ส่วนมือ (cls) และแต้มสะสมเลื่อนขั้นจะไม่ถูกแก้ย้อนหลัง เพราะต้องอาศัยลำดับเกมทั้งหมดหลังจากนั้นด้วย
  const editMatchResult = (recordId, newWinner) => {
    const record = matchRecords.find(r => r.id === recordId);
    if (!record || record.winner === newWinner) return;
    const { deltaA: newDeltaA, deltaB: newDeltaB } = computeEloDeltas(players, record.teamA, record.teamB, newWinner);
    const newPowerDeltas = {};
    record.teamA.forEach(id => { newPowerDeltas[id] = newDeltaA; });
    record.teamB.forEach(id => { newPowerDeltas[id] = newDeltaB; });

    setPlayers(prev => prev.map(p => {
      const oldDelta = record.powerDeltas?.[p.id];
      if (oldDelta === undefined) return p;
      const newDelta = newPowerDeltas[p.id];
      return { ...p, power: Math.max(MIN_POWER, p.power - oldDelta + newDelta) };
    }));
    setMatchRecords(prev => prev.map(r => r.id === recordId ? { ...r, winner: newWinner, powerDeltas: newPowerDeltas } : r));
  };

  // ลบประวัติทั้งวัน — เอาแมทช์ของวันนั้นออกจาก matchRecords ทั้งหมด (ยอดเงิน/สถิติ/ทำเนียบที่คำนวณจาก matchRecords จะหายไปเองตามไปด้วย)
  const deleteDayRecords = (dayKey) => {
    setMatchRecords(prev => prev.filter(r => dayKeyOf(r.timestamp) !== dayKey));
  };

  const markPaid = (id, method) => setPaidMap(prev => ({ ...prev, [id]: { paid: true, method } }));
  const unmarkPaid = (id) => setPaidMap(prev => { const next = { ...prev }; delete next[id]; return next; });

  const toggleBlock = (playerId, targetId) => {
    setPlayers(prev => prev.map(p => p.id !== playerId ? p : { ...p, blocked: p.blocked.includes(targetId) ? p.blocked.filter(x => x !== targetId) : [...p.blocked, targetId] }));
  };

  const setPhoto = (playerId, dataUrl) => {
    setPlayers(prev => prev.map(p => p.id === playerId ? { ...p, photo: dataUrl } : p));
  };

  const addPlayer = ({ name, fullName, phone, cls, gender, photo, power }) => {
    setPlayers(prev => {
      const nextId = prev.length ? Math.max(...prev.map(p => p.id)) + 1 : 1;
      const newPlayer = {
        id: nextId, name, fullName, phone, cls, gender, photo,
        played: 0, w: 0, l: 0, avatar: '🏸',
        bestDuo: '-', rival: '-', weapon: '-',
        blocked: [], isVeteran: false,
        power: power ?? (TIER_BASE_POWER[cls] + 50), // ใช้ค่าที่กรอกเอง ถ้าไม่ได้กรอกค่อย fallback ไปกึ่งกลางของมือที่เลือก
        tierPoints: 0,
      };
      return [...prev, newPlayer];
    });
  };

  const editPlayer = (id, { name, fullName, phone, cls, gender, photo, power }) => {
    setPlayers(prev => prev.map(p => {
      if (p.id !== id) return p;
      const changed = cls !== p.cls || power !== p.power;
      return {
        ...p, name, fullName, phone, cls, gender, photo, power,
        // แก้มือหรือพลังรบเองแบบ manual ถือเป็นจุดตั้งต้นใหม่ รีเซ็ตแต้มสะสมเลื่อนขั้น ถ้าไม่ได้แก้ทั้งคู่ก็คงเดิม
        tierPoints: changed ? 0 : (p.tierPoints || 0),
      };
    }));
  };

  const deletePlayer = (id) => {
    setPlayers(prev => prev.filter(p => p.id !== id));
    setCheckedInIds(prev => prev.filter(x => x !== id));
    setCourts(prev => prev.map(c => ({ ...c, players: c.players.map(p => (p && p.id === id) ? null : p) })));
  };

  const profilePlayer = useMemo(() => players.find(p => p.id === profileId), [players, profileId]);
  const pairStats = useMemo(() => computePairStats(matchRecords), [matchRecords]);
  const togetherCounts = useMemo(() => buildTogetherCounts(matchRecords), [matchRecords]);
  const todayGroupStats = useMemo(() => buildTodayGroupStats(matchRecords, players), [matchRecords, players]);
  const todayLukpatLowerGames = useMemo(() => countLukpatLowerGamesToday(matchRecords, players), [matchRecords, players]);
  const consecutiveCounts = useMemo(() => {
    const map = {};
    players.forEach(p => { map[p.id] = computeConsecutiveGames(matchRecords, p.id); });
    return map;
  }, [matchRecords, players]);

  const tabs = [
    { key: 'home', label: 'หน้าแรก', icon: <Target /> },
    { key: 'admin', label: 'แอดมิน', icon: <LayoutGrid /> },
    { key: 'board', label: 'ทำเนียบ', icon: <Trophy /> },
    { key: 'finance', label: 'การเงิน', icon: <Wallet /> },
    { key: 'history', label: 'ประวัติ', icon: <Clock /> },
  ];

  if (!isSynced) {
    return (
      <div className="min-h-screen bg-slate-950 text-white font-sans flex items-center justify-center p-4">
        <div className="flex flex-col items-center gap-3">
          <img src={MASCOT_BOY} alt="" className="w-16 h-16 object-contain mascot-wiggle" />
          <p className="text-sm text-slate-400">กำลังเชื่อมต่อฐานข้อมูล...</p>
        </div>
      </div>
    );
  }

  if (!isAuthenticated) {
    return (
      <PasswordGate
        appPassword={appPassword}
        onUnlock={() => setIsAuthenticated(true)}
        onChangePassword={setAppPassword}
      />
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 text-white font-sans flex flex-col md:flex-row selection:bg-cyan-500/30">
      {syncError && (
        <div className="fixed top-0 left-0 right-0 z-[200] bg-rose-950/95 border-b-2 border-rose-500 text-rose-200 text-xs text-center py-1.5 px-3">
          {syncError}
        </div>
      )}
      <style dangerouslySetInnerHTML={{ __html: `
        @import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;800&family=Kalam:wght@400;700&display=swap');
        h1, h2, h3 { font-family: 'Baloo 2', 'Kalam', sans-serif; }
        @keyframes gentleWiggle { 0%,100% { transform: rotate(-2deg); } 50% { transform: rotate(2deg); } }
        .mascot-wiggle:hover { animation: gentleWiggle 0.6s ease-in-out infinite; }

        /* สกินแถบเลื่อนให้เข้าธีมนีออนดำ-น้ำเงิน */
        * { scrollbar-width: thin; scrollbar-color: #22d3ee #0f172a; }
        *::-webkit-scrollbar { width: 8px; height: 8px; }
        *::-webkit-scrollbar-track { background: #0f172a; border-radius: 9999px; }
        *::-webkit-scrollbar-thumb {
          background: linear-gradient(180deg, #22d3ee, #3b82f6);
          border-radius: 9999px;
          border: 1px solid #0f172a;
          box-shadow: 0 0 6px rgba(34,211,238,0.6);
        }
        *::-webkit-scrollbar-thumb:hover {
          background: linear-gradient(180deg, #67e8f9, #60a5fa);
          box-shadow: 0 0 10px rgba(34,211,238,0.9);
        }
        *::-webkit-scrollbar-corner { background: transparent; }

        /* ขยายพื้นที่แตะปุ่มไอคอนล้วน (ไม่มีข้อความ) อัตโนมัติบนอุปกรณ์สัมผัส เช่น iPad/iPhone
           เพื่อให้กดง่ายขึ้นโดยไม่ต้องแก้ไขทุกปุ่มในโค้ดทีละจุด */
        @media (pointer: coarse) {
          button:has(> svg:only-child) {
            min-width: 40px;
            min-height: 40px;
          }
        }
      `}} />

      <aside className="hidden md:flex flex-col w-64 bg-slate-900 border-r-[3px] border-slate-700 p-4 h-screen sticky top-0">
        <div className="mb-10 pl-1"><Logo /></div>
        <nav className="space-y-2 flex-1">
          {tabs.map(t => (
            <button key={t.key} onClick={() => setTab(t.key)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left transition-colors border-2 ${tab === t.key ? 'bg-cyan-950/40 border-slate-700 text-white' : 'text-slate-400 border-transparent hover:bg-slate-950 hover:text-white'}`}>
              {React.cloneElement(t.icon, { className: `w-5 h-5 ${tab === t.key ? 'text-cyan-600' : 'text-slate-500'}` })}
              <span className="font-medium text-sm">{t.label}</span>
            </button>
          ))}
        </nav>
      </aside>

      <header className="md:hidden flex items-center justify-between p-4 bg-slate-900 border-b-[3px] border-slate-700 sticky top-0 z-40">
        <Logo size="sm" /><Bell className="text-slate-300 w-6 h-6" />
      </header>

      <main className="flex-1 pb-24 md:pb-0">
        <div className="p-4 md:p-8 max-w-6xl mx-auto">
          {tab === 'home' && <CheckInPage players={players} checkedInIds={checkedInIds} onToggleCheckIn={toggleCheckIn} onOpenProfile={setProfileId} onAddPlayer={addPlayer} onEditPlayer={editPlayer} onDeletePlayer={deletePlayer} />}
          {tab === 'admin' && <AdminPage players={players} checkedInIds={checkedInIds} courts={courts} setCourts={setCourts} onGameEnd={handleGameEnd} onOpenProfile={setProfileId} pairStats={pairStats} togetherCounts={togetherCounts} todayGroupStats={todayGroupStats} todayLukpatLowerGames={todayLukpatLowerGames} consecutiveCounts={consecutiveCounts} restingIds={restingIds} onToggleResting={toggleResting} paidMap={paidMap} />}
          {tab === 'board' && <LeaderboardPage players={players} attendance={attendance} />}
          {tab === 'finance' && <FinancePage players={players} matchRecords={matchRecords} paidMap={paidMap} onMarkPaid={markPaid} onUnmarkPaid={unmarkPaid} dailyPrices={dailyPrices} onChangeTodayPrice={changeTodayPrice} />}
          {tab === 'history' && <HistoryPage matchRecords={matchRecords} players={players} onEditResult={editMatchResult} dailyPrices={dailyPrices} onDeleteDay={deleteDayRecords} />}
        </div>
      </main>

      <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-slate-900 border-t-[3px] border-slate-700 flex z-40">
        {tabs.map(t => (
          <button key={t.key} onClick={() => setTab(t.key)} className={`flex-1 flex flex-col items-center gap-1 py-3 ${tab === t.key ? 'text-cyan-600' : 'text-cyan-500'}`}>
            {React.cloneElement(t.icon, { className: 'w-5 h-5' })}
            <span className="text-[10px] font-bold">{t.label}</span>
          </button>
        ))}
      </nav>

      <ProfileModal player={profilePlayer} allPlayers={players} onClose={() => setProfileId(null)} onToggleBlock={toggleBlock} onSetPhoto={setPhoto} pairStats={pairStats} matchRecords={matchRecords} />
    </div>
  );
}
